export const PROGRAM_LUCRU_HTML = "<!DOCTYPE html>\r\n<html lang=\"ro\">\r\n<head>\r\n<meta charset=\"UTF-8\">\r\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\r\n<title>Program de lucru pe cazuri · salvează o inimă</title>\r\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\r\n<link href=\"https://fonts.googleapis.com/css2?family=Fraunces:opsz,wght@9..144,600;9..144,700&family=Inter:wght@400;500;600;700&display=swap\" rel=\"stylesheet\">\r\n<style>\r\n:root{\r\n  --parchment:#FBF7EF; --paper:#fff; --ink:#2B2320; --muted:#8A7E70;\r\n  --red:#C22B33; --red-deep:#9E1F27; --red-soft:#F7E5E4; --line:#EAE1D2;\r\n  --amber:#B57C22; --amber-soft:#F6ECD9; --green:#3E7C4F; --green-soft:#E4EFE6;\r\n  --blue:#39618E; --blue-soft:#E3EAF2; --purple:#6C4A8E; --purple-soft:#EFE7F4;\r\n  --teal:#2E6E7E; --teal-soft:#E4EEF2;\r\n  --display:'Fraunces',Georgia,serif; --body:'Inter',system-ui,sans-serif;\r\n}\r\n*{box-sizing:border-box;margin:0;padding:0}\r\nbody{font-family:var(--body);background:var(--parchment);color:var(--ink);font-size:15px;line-height:1.5;-webkit-font-smoothing:antialiased;padding-bottom:80px}\r\n.wrap{max-width:980px;margin:0 auto;padding:24px 16px}\r\nheader{display:flex;align-items:center;gap:14px;margin-bottom:12px;flex-wrap:wrap}\r\nh1{font-family:var(--display);font-weight:700;font-size:23px;letter-spacing:-.015em}\r\nh1 small{display:block;font-family:var(--body);font-weight:500;font-size:12.5px;color:var(--muted)}\r\n.userbox{margin-left:auto;display:flex;align-items:center;gap:8px;font-size:12.5px;color:var(--muted)}\r\nselect,input[type=text],input[type=date],input[type=number]{padding:9px 11px;border:1px solid var(--line);border-radius:10px;background:var(--paper);font-family:var(--body);font-size:14px;color:var(--ink);outline:none}\r\n.userbox select{border:1.5px solid var(--red);font-weight:600;color:var(--red-deep)}\r\ninput:focus,select:focus{border-color:var(--red);box-shadow:0 0 0 3px var(--red-soft)}\r\n.btn{display:inline-flex;align-items:center;gap:7px;padding:10px 15px;border-radius:11px;border:1px solid var(--line);background:var(--paper);font-family:var(--body);font-size:13.5px;font-weight:600;color:var(--ink);cursor:pointer;transition:all .12s}\r\n.btn:hover{border-color:#D8CCB8;box-shadow:0 2px 8px rgba(43,35,32,.08)}\r\n.btn.small{padding:6px 11px;font-size:12px;border-radius:9px}\r\n.btn.primary{background:var(--red);border-color:var(--red);color:#fff}\r\n.chipbtn{padding:9px 15px;border-radius:99px;border:1px solid var(--line);background:var(--paper);font-size:13px;font-weight:600;color:var(--muted);cursor:pointer;font-family:var(--body)}\r\n.chipbtn.on{background:var(--ink);border-color:var(--ink);color:var(--parchment)}\r\n.chipbtn .bdg{display:inline-block;background:var(--red);color:#fff;border-radius:99px;font-size:11px;padding:1px 7px;margin-left:6px;font-weight:700}\r\n.tabs{display:flex;gap:8px;flex-wrap:wrap;margin-bottom:14px}\r\n.toolrow{display:flex;gap:8px;flex-wrap:wrap;align-items:center;margin-bottom:14px}\r\n.info{background:var(--blue-soft);color:var(--blue);border-radius:12px;padding:11px 15px;font-size:12.5px;margin-bottom:14px}\r\n.warn{background:var(--amber-soft);color:var(--amber);border-radius:12px;padding:11px 15px;font-size:12.5px;margin-bottom:14px}\r\n.alarm{background:var(--red);color:#fff;border-radius:12px;padding:12px 16px;font-size:13.5px;margin-bottom:14px;display:flex;align-items:center;gap:10px;flex-wrap:wrap}\r\n.alarm button{margin-left:auto}\r\n.card{background:var(--paper);border:1px solid var(--line);border-radius:14px;margin-bottom:12px;overflow:hidden}\r\n.chead{display:flex;align-items:center;gap:10px;padding:12px 15px;border-bottom:1px solid var(--line);background:#FEFCF8;flex-wrap:wrap}\r\n.chead b{font-family:var(--display);font-size:16px}\r\n.chead .sub{font-size:12px;color:var(--muted);font-weight:600}\r\n.chead .right{margin-left:auto;display:flex;gap:7px;align-items:center}\r\n.slot{display:flex;gap:12px;align-items:flex-start;padding:10px 15px;border-top:1px solid #F4EFE6}\r\n.slot:first-child{border-top:none}\r\n.slot .hh{font-variant-numeric:tabular-nums;font-weight:700;font-size:13px;color:var(--muted);flex:none;width:102px;padding-top:1px}\r\n.slot.break{background:var(--amber-soft)}\r\n.slot.break .hh,.slot.break .bd{color:var(--amber);font-weight:600}\r\n.slot.over{background:var(--red-soft)}\r\n.slot.flex{background:#FDFBF6}\r\n.slot.flex .bd{color:var(--muted)}\r\n.tag.tflex{background:var(--teal-soft);color:var(--teal)}\r\n.slot input[type=checkbox]{margin-top:2px;width:17px;height:17px;accent-color:var(--red);flex:none;cursor:pointer}\r\n.slot.done .bd{text-decoration:line-through;color:var(--muted)}\r\n.bd{flex:1;font-size:14px;line-height:1.45}\r\n.byline{display:block;font-size:11px;color:var(--muted);margin-top:2px;text-decoration:none}\r\n.tag{display:inline-block;font-size:10.5px;font-weight:700;padding:2px 8px;border-radius:99px;margin-right:7px;vertical-align:1px;white-space:nowrap}\r\n.t7{background:var(--red-soft);color:var(--red-deep)}\r\n.t15{background:var(--amber-soft);color:var(--amber)}\r\n.t30{background:var(--blue-soft);color:var(--blue)}\r\n.t60{background:var(--green-soft);color:var(--green)}\r\n.tgen{background:#F1ECE2;color:var(--muted)}\r\n.trsp{background:var(--purple-soft);color:var(--purple)}\r\n.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:10px;margin-bottom:14px}\r\n.stat{background:var(--paper);border:1px solid var(--line);border-radius:13px;padding:11px 13px;cursor:pointer}\r\n.stat.on{border-color:var(--red);box-shadow:0 0 0 3px var(--red-soft)}\r\n.stat .who{font-weight:700;font-size:13.5px}\r\n.stat .nums{font-family:var(--display);font-size:19px;margin:2px 0}\r\n.stat .nums small{font-size:12px;color:var(--muted);font-family:var(--body)}\r\n.pbar{height:5px;background:#F1ECE2;border-radius:99px;overflow:hidden}\r\n.pbar i{display:block;height:100%;background:var(--red)}\r\n.pbar i.full{background:var(--amber)}\r\n.pbar i.over{background:var(--red-deep)}\r\n.frow{display:flex;gap:9px;flex-wrap:wrap;align-items:center;padding:12px 15px;border-top:1px solid #F4EFE6}\r\n.frow label{font-size:12px;font-weight:700;color:var(--muted)}\r\n.freqhead{font-size:11.5px;font-weight:700;text-transform:uppercase;letter-spacing:.06em;color:var(--muted);padding:12px 15px 4px}\r\n.empty{text-align:center;color:var(--muted);padding:32px;font-size:14px}\r\n.toast{position:fixed;bottom:22px;left:50%;transform:translateX(-50%);background:var(--ink);color:var(--parchment);padding:11px 20px;border-radius:99px;font-size:13.5px;font-weight:600;opacity:0;transition:opacity .25s;pointer-events:none;z-index:99}\r\n.mini{font-size:12px;color:var(--muted)}\r\n.fin{padding:14px 16px 18px}\r\n.finhead{display:flex;align-items:baseline;gap:9px;margin-bottom:12px;flex-wrap:wrap}\r\n.finhead .sum{font-family:var(--display);font-size:26px;font-weight:700;color:var(--ink);line-height:1}\r\n.finhead .din{font-size:13.5px;color:var(--muted);font-weight:600}\r\n.finhead .pct{margin-left:auto;font-family:var(--display);font-size:22px;font-weight:700;padding:2px 13px;border-radius:99px}\r\n.pct.p0{background:#F1ECE2;color:var(--muted)}\r\n.pct.p25{background:var(--red-soft);color:var(--red-deep)}\r\n.pct.p50{background:var(--amber-soft);color:var(--amber)}\r\n.pct.p75{background:var(--blue-soft);color:var(--blue)}\r\n.pct.p100{background:var(--green-soft);color:var(--green)}\r\n.track{position:relative;height:22px;border-radius:99px;background:linear-gradient(90deg,#F3EDE2,#EFE8DC);box-shadow:inset 0 1px 3px rgba(43,35,32,.10);overflow:hidden;margin-bottom:5px}\r\n.track .fill{position:absolute;left:0;top:0;bottom:0;border-radius:99px;background:linear-gradient(90deg,#C22B33 0%,#D9752B 38%,#C9A227 62%,#3E7C4F 100%);background-size:340px 100%;transition:width .35s cubic-bezier(.34,1.2,.64,1);box-shadow:0 1px 6px rgba(194,43,51,.30)}\r\n.track .fill.done{background:linear-gradient(90deg,#3E7C4F,#57A06B)}\r\n.track .shine{position:absolute;inset:0;background:linear-gradient(180deg,rgba(255,255,255,.35),rgba(255,255,255,0) 55%);pointer-events:none}\r\n.track .mk{position:absolute;top:0;bottom:0;width:2px;background:rgba(255,255,255,.75);z-index:2}\r\n.marks{position:relative;height:16px;margin-bottom:9px}\r\n.marks span{position:absolute;transform:translateX(-50%);font-size:10.5px;font-weight:700;color:var(--muted);white-space:nowrap}\r\n.marks span.hit{color:var(--green)}\r\ninput[type=range].fs{-webkit-appearance:none;appearance:none;width:100%;height:26px;background:transparent;cursor:pointer;outline:none}\r\ninput[type=range].fs::-webkit-slider-runnable-track{height:6px;border-radius:99px;background:var(--line)}\r\ninput[type=range].fs::-webkit-slider-thumb{-webkit-appearance:none;height:22px;width:22px;margin-top:-8px;border-radius:50%;background:#fff;border:3px solid var(--red);box-shadow:0 2px 7px rgba(43,35,32,.25)}\r\ninput[type=range].fs::-moz-range-track{height:6px;border-radius:99px;background:var(--line)}\r\ninput[type=range].fs::-moz-range-thumb{height:19px;width:19px;border-radius:50%;background:#fff;border:3px solid var(--red);box-shadow:0 2px 7px rgba(43,35,32,.25)}\r\n.prag{display:flex;gap:8px;flex-wrap:wrap;padding:10px 15px}\r\n.pragbtn{border:1px solid var(--line);background:var(--paper);border-radius:10px;padding:7px 13px;font-size:12.5px;font-weight:700;cursor:pointer;font-family:var(--body);color:var(--muted)}\r\n.pragbtn.on{background:var(--green-soft);border-color:var(--green);color:var(--green)}\r\n.loadbar{display:flex;gap:6px;padding:10px 15px;flex-wrap:wrap}\r\n.lb{flex:1;min-width:88px;background:#FBF7EF;border-radius:10px;padding:7px 9px;font-size:11.5px}\r\n.lb b{display:block;font-size:12.5px}\r\n.lb.ok{color:var(--green)} .lb.mid{color:var(--amber)} .lb.bad{color:var(--red-deep);background:var(--red-soft)}\r\n@media(max-width:560px){.slot .hh{width:76px;font-size:12px}}\r\n</style>\r\n<style>button[title=\"Sincronizare între calculatoare\"]{display:none!important}</style><script defer src=\"/vendor/html2pdf.bundle.min.js\"></script></head>\r\n<body>\r\n<div class=\"wrap\">\r\n<header>\r\n  <img src=\"data:image/png;base64,\" alt=\"salvează o inimă\" style=\"height:56px;width:auto;flex:none\">\r\n  <h1>Program de lucru pe cazuri<small>echipa de fundraising · 8:30–15:30 · rutina fiecăreia + cazurile active, intercalate fără suprapunere</small></h1>\r\n  <div class=\"userbox\">Eu sunt:\r\n    <select id=\"whoami\" onchange=\"setUser(this.value)\">\r\n      <option value=\"\">— alege —</option>\r\n      <option>Andreea</option><option>Paula</option><option>Ștefania</option>\r\n      <option>Vlad</option><option>Gabriel</option><option>Andrei</option>\r\n    </select>\r\n  </div>\r\n</header>\r\n\r\n<div id=\"alarmbox\"></div>\r\n\r\n<div class=\"tabs\">\r\n  <button class=\"chipbtn on\" id=\"tab_zi\" onclick=\"setView('zi')\">📅 Ziua mea</button>\r\n  <button class=\"chipbtn\" id=\"tab_caz\" onclick=\"setView('caz')\">🗂 Cazuri</button>\r\n  <button class=\"chipbtn\" id=\"tab_final\" onclick=\"setView('final')\">✅ Finalizate</button>\r\n  <button class=\"chipbtn\" id=\"tab_rest\" onclick=\"setView('rest')\">⏰ Restanțe<span class=\"bdg\" id=\"restbdg\" style=\"display:none\">0</span></button>\r\n  <button class=\"chipbtn\" id=\"tab_extra\" onclick=\"setView('extra')\">📌 Sarcini colegi<span class=\"bdg\" id=\"extrabdg\" style=\"display:none\">0</span></button>\r\n  <button class=\"chipbtn\" id=\"tab_fisa\" onclick=\"setView('fisa')\">📋 Fișele postului</button>\r\n</div>\r\n\r\n<div class=\"toolrow\" id=\"toolrow\"></div>\r\n<div id=\"out\"><div class=\"empty\">Se încarcă…</div></div>\r\n</div>\r\n<input type=\"file\" id=\"fisier\" accept=\"application/json\" style=\"display:none\" onchange=\"incarcaProiect(this)\">\r\n<div class=\"toast\" id=\"toast\"></div>\r\n<script>\r\n/* ================== CONSTANTE ================== */\r\nconst ECHIPA=['Andreea','Paula','Ștefania','Vlad'];\r\nconst FETELE=['Andreea','Paula','Ștefania']; /* fundraising — ascunse față de Gabriel/Andrei */\r\nconst ROL={Andreea:'Manager Fundraising — presă & firme calde',Paula:'Manager Fundraising — companii locale & voluntari','Ștefania':'Asistent Manager Fundraising — conținut social',Vlad:'Coordonator — plăți, dezvoltare, conținut & campanie'};\r\nconst RESPONSABILI=['Paula','Andreea','Ștefania'];\r\nconst TOTI=['Andreea','Paula','Ștefania','Vlad','Gabriel','Andrei'];\r\nfunction eFata(p){return FETELE.indexOf(p)>=0;}\r\nfunction eExtern(p){return p==='Gabriel'||p==='Andrei';} /* în afara programului de fundraising */\r\nconst TIERS={\r\n  7:{lab:'Foarte urgent',cls:'t7',pr:1,posts:15,upd:1},\r\n  15:{lab:'Urgent',cls:'t15',pr:2,posts:15,upd:2},\r\n  30:{lab:'30 de zile',cls:'t30',pr:3,posts:12,upd:3},\r\n  60:{lab:'60 de zile',cls:'t60',pr:4,posts:8,upd:5}\r\n};\r\nconst ZILE=['duminică','luni','marți','miercuri','joi','vineri','sâmbătă'];\r\nconst LUNI=['ian','feb','mar','apr','mai','iun','iul','aug','sep','oct','nov','dec'];\r\nconst M=(h,m)=>h*60+(m||0);\r\nconst CITIT=[M(8,30),M(9,0)], BLOC1=[M(9,0),M(12,0)], MASA=[M(12,0),M(12,30)], BLOC2=[M(12,30),M(15,10)], INCHIDERE=[M(15,10),M(15,30)];\r\nconst SEDINTA=[M(9,0),M(9,30)];\r\nconst PRAG_RESTANTE=10;\r\nconst MAX_CAZ=4;\r\nconst primaMarti=iso=>dow(iso)===2&&+iso.slice(8)<=7;\r\nfunction lunaUrm(){const d=todayIso();const y=+d.slice(0,4),m=+d.slice(5,7);const ny=m===12?y+1:y,nm=m===12?1:m+1;return ny+'-'+String(nm).padStart(2,'0')+'-01';}\r\nfunction fmtLuna(iso){return ['ianuarie','februarie','martie','aprilie','mai','iunie','iulie','august','septembrie','octombrie','noiembrie','decembrie'][+iso.slice(5,7)-1]+' '+iso.slice(0,4);}\r\n/* cazuri intensive începute în luna curentă */\r\nfunction intensiveLunaCurenta(){const l=todayIso().slice(0,7);return CAZURI.filter(c=>!c.sters&&(c.mod||'intens')==='intens'&&c.start.slice(0,7)===l);}\r\nconst ZI_SEDINTA=5;\r\nconst bloc1For=iso=>[dow(iso)===ZI_SEDINTA?SEDINTA[1]:BLOC1[0],BLOC1[1]];\r\nlet RESTP={}, BLOCATI=[];\r\nconst CAPACITATE=(BLOC1[1]-BLOC1[0])+(BLOC2[1]-BLOC2[0]);\r\nconst PROGRAM_MAX=300; /* program clar de 5 ore de sarcini pe zi — nimic nu depășește */\r\nconst hhmm=v=>String(Math.floor(v/60)).padStart(2,'0')+':'+String(v%60).padStart(2,'0');\r\n\r\n/* sarcini care umplu golurile — utile, nu umplutură */\r\nconst FLEX={\r\n Andreea:['Sună 3 companii care au refuzat anul trecut — între timp s-au schimbat bugetele',\r\n   'Actualizează lista de jurnaliști: cine mai scrie despre sănătate, ce contact avem',\r\n   'Scrie o poveste de succes pentru site, dintr-un caz încheiat',\r\n   'Verifică mențiunile asociației în presă din ultima săptămână',\r\n   'Pregătește întrebările pentru următorul interviu cu o familie',\r\n   'Revizuiește un comunicat vechi și fă din el un șablon refolosibil',\r\n   'Caută 5 fundații și programe de finanțare pentru care ne calificăm'],\r\n Paula:['Reactivare firme: sună 5 companii care au donat anul trecut',\r\n   'Verifică ce grupuri au devenit inactive și scoate-le din lot',\r\n   'Sună 5 voluntari noi din listă și explică-le cum lucrăm',\r\n   'Pregătește materiale pentru voluntari: texte gata de copiat, imagini',\r\n   'Curăță CRM-ul de duplicate și contacte moarte',\r\n   'Caută grupuri noi în județele unde nu avem acoperire',\r\n   'Fă lista firmelor din zona următorului caz, înainte să-l preluăm'],\r\n 'Ștefania':['Analizează ce postări au mers cel mai bine și notează tiparul',\r\n   'Pregătește 3 șabloane de carduri pentru pragurile următoare',\r\n   'Colectează testimoniale de la familiile cazurilor încheiate',\r\n   'Planifică o serie de storyuri pentru săptămâna viitoare',\r\n   'Arhivează materialele cazurilor închise, pe foldere',\r\n   'Caută conturi și pagini noi de urmărit pentru distribuire',\r\n   'Scrie textele de mulțumire gata de folosit la praguri'],\r\n Vlad:['Verifică facturile scadente și statusul plăților',\r\n   'Idei de îmbunătățire pentru generatoare — notează și prioritizează',\r\n   'Analiză rapidă a traficului pe site și a conversiilor',\r\n   'Pregătește conținut pentru postările de mâine']\r\n};\r\n/* ================== STARE ================== */\r\nlet CAZURI=[], BIFE={}, PRAGURI={}, EXTRA=[], OVERRIDES={}, ABSENTI={}, RUTINA_CUSTOM=[], RUTINA_OFF={}, ROVR={}, USER='', VIEW='zi', ZI=todayIso(), FILTRU='', FORM=false, EDITCAZ='', EDITEXTRA='', EDITSLOT='', EDITCONCEDIU='', EDITRUTINA='';\r\nfunction hashStr(s){let h=0;s=String(s);for(let i=0;i<s.length;i++)h=(h*31+s.charCodeAt(i))|0;return h;}\r\nconst uid=()=>'c'+Date.now().toString(36)+Math.random().toString(36).slice(2,5);\r\nconst esc=s=>String(s??'').replace(/[&<>\"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[c]));\r\nconst slug=s=>(s||'x').toLowerCase().normalize('NFD').replace(/[\\u0300-\\u036f]/g,'').replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'')||'x';\r\nfunction todayIso(){const d=new Date();return new Date(d.getTime()-d.getTimezoneOffset()*6e4).toISOString().slice(0,10);}\r\nfunction addDays(iso,n){const d=new Date(iso+'T12:00:00');d.setDate(d.getDate()+n);return d.toISOString().slice(0,10);}\r\nfunction dow(iso){return new Date(iso+'T12:00:00').getDay();}\r\nfunction diffDays(a,b){return Math.round((new Date(b+'T12:00:00')-new Date(a+'T12:00:00'))/864e5);}\r\nfunction fmtZi(iso){const d=new Date(iso+'T12:00:00');return ZILE[d.getDay()]+', '+d.getDate()+' '+LUNI[d.getMonth()];}\r\nfunction ziuaLucrUrm(iso){let d=addDays(iso,1),g=0;while((dow(d)===0||dow(d)===6)&&g++<7)d=addDays(d,1);return d;}\r\n\r\n/* ================== SALVARE AUTOMATĂ ==================\r\n   Fiecare modificare se scrie imediat în DOUĂ locuri:\r\n   1. localStorage — pe acest calculator (merge și fără internet, nu se pierde la refresh)\r\n   2. spațiul partajat (window.storage) — văzut de toată echipa, dacă e disponibil\r\n   La încărcare câștigă copia cea mai recentă. Butonul 💾 rămâne doar copie de siguranță. */\r\nlet PENDING=0, INCARCAT=false, ULTIMA_SALVARE='', SYNC_PORNIT=false, NOTIFICATE=[];\r\nlet ST_LOCAL=false, ST_CLOUD=false, ST_NET=false, TESTAT=false, SETARI=false, SYNC_URL='';\r\nlet STERSE_RECENT={}; /* ce am șters intenționat de curând (sesiunea asta, 1h) */\r\nlet TOMBS={};          /* tombstone-uri persistate + sincronizate: TOMBS[k]={t:ISO,d:1|0}\r\n                          d:1 = șters (nu reapare la merge, chiar și de pe alt calculator),\r\n                          d:0 = re-adăugat (anulează un tombstone anterior); TTL 45 zile */\r\nlet _tombTimer=null;\r\nfunction programSaveTomb(){ if(typeof setTimeout!=='function'){saveTomb();return;} if(_tombTimer)clearTimeout(_tombTimer); _tombTimer=setTimeout(saveTomb,600); }\r\nconst marcheazaSters=k=>{ STERSE_RECENT[k]=Date.now(); TOMBS[k]={t:acum(),d:1}; programSaveTomb(); };\r\nconst revine=k=>{ delete STERSE_RECENT[k]; TOMBS[k]={t:acum(),d:0}; programSaveTomb(); };\r\nconst stersRecent=k=>{\r\n  if(STERSE_RECENT[k]&&(Date.now()-STERSE_RECENT[k])<36e5) return true;\r\n  const tb=TOMBS[k];\r\n  return !!(tb && tb.d===1 && tb.t && (Date.now()-Date.parse(tb.t))<45*864e5);\r\n};\r\n/* cheia unei sarcini de rutină e „rut|<data>|<pers>|<titlu>\"; stratul permanent\r\n   ROVR e cheiat fără dată (pers|titlu), ca să se aplice în toate zilele */\r\nconst isRutKey=k=>String(k).indexOf('rut|')===0;\r\nconst rovrKey=k=>String(k).split('|').slice(2).join('|');\r\n/* Andrei poate lipi aici linkul bazei, ca fișierul trimis colegelor să vină gata conectat: */\r\nconst SYNC_IMPLICIT='/api/program-sync';\r\nfunction citesteSyncUrl(){\r\n  let u=''; try{u=localStorage.getItem('soi-plan2-sync-url')||'';}catch(e){}\r\n  SYNC_URL=SYNC_IMPLICIT;\r\n  return SYNC_URL;\r\n}\r\nfunction urlCheie(key){\r\n  let b=(SYNC_URL||'').trim().replace(/\\/+$/,'');\r\n  if(!b)return '';\r\n  if(b.toLowerCase().endsWith('.json'))b=b.slice(0,-5);\r\n  return b+'/'+key+'.json';\r\n}\r\n/* Timp de SERVER: fiecare răspuns de la punte are antetul HTTP „Date\" (ceasul\r\n   serverului). Calculăm offset-ul față de ceasul local, ca timestamp-urile de\r\n   merge să fie aliniate între calculatoare, chiar dacă un PC are ceasul greșit. */\r\nlet CLOCK_OFFSET=0, CLOCK_SET=false;\r\nfunction syncClock(r){\r\n  try{ const d=r&&r.headers&&r.headers.get&&r.headers.get('date'); if(!d)return;\r\n    const st=Date.parse(d); if(isFinite(st)){ CLOCK_OFFSET=st-Date.now(); CLOCK_SET=true; } }catch(e){}\r\n}\r\nasync function netSet(key,s){\r\n  const u=urlCheie(key); if(!u||typeof fetch!=='function')return false;\r\n  try{const r=await fetch(u,{method:'PUT',headers:{'Content-Type':'application/json'},body:s});syncClock(r);return r.ok;}\r\n  catch(e){return false;}\r\n}\r\nasync function netGet(key){\r\n  const u=urlCheie(key); if(!u||typeof fetch!=='function')return null;\r\n  try{const r=await fetch(u,{cache:'no-store'}); syncClock(r); if(!r.ok)return null;\r\n      const j=await r.json(); if(j==null)return null;\r\n      return desfasoara(typeof j==='string'?JSON.parse(j):j);}\r\n  catch(e){return null;}\r\n}\r\n/* la pornire verificăm CU ADEVĂRAT unde putem salva, printr-o scriere de probă */\r\nasync function testStocare(){\r\n  try{localStorage.setItem('soi-plan2-test','1');\r\n      ST_LOCAL=localStorage.getItem('soi-plan2-test')==='1';\r\n      localStorage.removeItem('soi-plan2-test');}\r\n  catch(e){ST_LOCAL=false;}\r\n  ST_CLOUD=false;\r\n  if(window.storage){\r\n    try{await window.storage.set('soi-plan2-test','1',true);ST_CLOUD=true;}\r\n    catch(e){ST_CLOUD=false;}\r\n  }\r\n  ST_NET=false;\r\n  if(citesteSyncUrl())ST_NET=await netSet('soi-plan2-test',JSON.stringify(infasoara('1')));\r\n  TESTAT=true;\r\n}\r\nfunction stareText(){\r\n  if(!TESTAT)return 'se verifică salvarea…';\r\n  if(ST_NET)return '🌐 salvare automată, partajată cu echipa'+(ULTIMA_SALVARE?' · '+ULTIMA_SALVARE:'');\r\n  if(ST_CLOUD)return '☁️ salvare automată, partajată cu echipa'+(ULTIMA_SALVARE?' · '+ULTIMA_SALVARE:'');\r\n  if(ST_LOCAL)return '💻 salvat automat DOAR pe acest calculator — apasă ⚙️ pentru sincronizare cu colegele'+(ULTIMA_SALVARE?' · '+ULTIMA_SALVARE:'');\r\n  return '⚠️ AICI NU SE POATE SALVA';\r\n}\r\nfunction arataAutosave(){\r\n  ULTIMA_SALVARE=new Date().toLocaleTimeString('ro-RO',{hour:'2-digit',minute:'2-digit'});\r\n  const el=document.getElementById('autosv');\r\n  if(el){el.textContent=stareText();el.style.cssText=(ST_LOCAL||ST_CLOUD||ST_NET)?'':'color:var(--red-deep);font-weight:700';}\r\n}\r\nconst infasoara=v=>({_e:1,salvatLa:acum(),de:USER||'',data:v});\r\nconst desfasoara=o=>(o&&o._e===1)?o:{_e:1,salvatLa:'',de:'',data:o};\r\nasync function save(key,val){\r\n  const s=JSON.stringify(infasoara(val));\r\n  let okL=false, okC=false, okN=false;\r\n  try{localStorage.setItem(key,s);okL=true;}catch(e){}\r\n  PENDING++;\r\n  try{\r\n    if(window.storage){try{await window.storage.set(key,s,true);okC=true;}catch(e){console.error(e);}}\r\n    if(SYNC_URL)okN=await netSet(key,s);\r\n  }finally{PENDING--;}\r\n  ST_LOCAL=okL; if(window.storage)ST_CLOUD=okC; if(SYNC_URL)ST_NET=okN;\r\n  if(okN){ /* semnalăm celorlalte calculatoare că e ceva nou de preluat */\r\n    const pl=infasoara(1); PULS_CUNOSCUT=pl.salvatLa;\r\n    netSet('soi-plan2-puls',JSON.stringify(pl));\r\n  }\r\n  arataAutosave();\r\n  if(!okL&&!okC&&!okN)toast('⚠️ NU s-a putut salva — vezi avertismentul roșu de sus');\r\n  else if(SYNC_URL&&!okN)toast('⚠️ Salvat doar pe acest calculator — internetul sau linkul de sincronizare nu răspunde');\r\n}\r\nasync function loadSurse(key){\r\n  const out=[];\r\n  try{const s=localStorage.getItem(key); if(s!=null)out.push(desfasoara(JSON.parse(s)));}catch(e){}\r\n  if(window.storage){\r\n    try{const r=await window.storage.get(key,true); if(r&&r.value!=null)out.push(desfasoara(JSON.parse(r.value)));}\r\n    catch(e){}\r\n  }\r\n  if(SYNC_URL){const n=await netGet(key); if(n)out.push(n);}\r\n  out.sort((a,b)=>(a.salvatLa||'')<(b.salvatLa||'')?1:-1); /* cea mai nouă prima */\r\n  return out;\r\n}\r\nasync function load(key){const srs=await loadSurse(key);return srs.length?srs[0].data:null;}\r\n/* îmbinare per element: nimic nu se pierde, chiar dacă sursele au istorii diferite */\r\nfunction acum(){return new Date(Date.now()+CLOCK_OFFSET).toISOString();}\r\nfunction imbinaListe(surse){\r\n  const m=new Map();\r\n  surse.slice().reverse().forEach(env=>{  /* de la veche la nouă */\r\n    const arr=env&&env.data; if(!Array.isArray(arr))return;\r\n    arr.forEach(it=>{\r\n      if(!it||!it.id)return;\r\n      const ex=m.get(it.id);\r\n      if(!ex||(it.mod_la||'')>=(ex.mod_la||''))m.set(it.id,it);\r\n    });\r\n  });\r\n  return [...m.values()];\r\n}\r\nfunction imbinaObiect(surse,tombPrefix){\r\n  const baza=Object.assign({},(surse[0]&&surse[0].data&&typeof surse[0].data==='object')?surse[0].data:{});\r\n  surse.slice(1).forEach(env=>{\r\n    const o=env&&env.data; if(!o||typeof o!=='object')return;\r\n    for(const k in o){if(!(k in baza)&&!stersRecent(tombPrefix+k))baza[k]=o[k];}\r\n  });\r\n  /* aplică tombstone-urile: o cheie ștearsă nu rămâne nici dacă acest calculator\r\n     o mai avea în bază — altfel ar re-publica-o la următoarea salvare */\r\n  for(const k in baza){ if(stersRecent(tombPrefix+k)) delete baza[k]; }\r\n  return baza;\r\n}\r\n/* îmbinare specială pentru BIFE: fiecare bifă are timestamp propriu (ts). O\r\n   debifare (tombstone bifa-<k> cu d:1) ȘTERGE bifa DOAR dacă e mai nouă decât\r\n   bifa — altfel o rebifare rămâne, chiar dacă un calculator mai are un tombstone\r\n   vechi de debifare. Rezolvă „bifa nu rămâne tăiată\" între dispozitive. */\r\nfunction imbinaBife(surse){\r\n  const baza={};\r\n  surse.forEach(env=>{ const o=env&&env.data; if(!o||typeof o!=='object')return;\r\n    for(const k in o){ const v=o[k]; if(!v)continue;\r\n      if(!baza[k]||((v.ts||'')>=(baza[k].ts||'')))baza[k]=v; } /* per-cheie, cea mai nouă bifă câștigă */\r\n  });\r\n  for(const k in baza){\r\n    const tb=TOMBS['bifa-'+k], tdel=(tb&&tb.d===1)?(tb.t||''):'';\r\n    if(tdel&&tdel>(baza[k].ts||''))delete baza[k];               /* debifare mai nouă decât bifa (acoperă și bifele vechi fără ts, tdel>'') */\r\n  }\r\n  return baza;\r\n}\r\n/* tombstone-urile se îmbină per-cheie după timp (cel mai nou eveniment câștigă:\r\n   ștergere vs re-adăugare) */\r\nfunction imbinaTomb(surse){\r\n  const m={};\r\n  surse.forEach(env=>{ const o=env&&env.data; if(!o||typeof o!=='object')return;\r\n    for(const k in o){ const v=o[k]; if(!v)continue; if(!m[k]||((v.t||'')>(m[k].t||'')))m[k]=v; }\r\n  });\r\n  return m;\r\n}\r\nasync function saveTomb(){\r\n  const srs=await loadSurse('soi-plan2-tombs');\r\n  TOMBS=imbinaTomb([{salvatLa:acum(),data:TOMBS}].concat(srs));\r\n  return save('soi-plan2-tombs',TOMBS);\r\n}\r\n/* înainte de a scrie, îmbinăm cu ce au salvat colegele între timp — nimeni nu șterge munca altcuiva */\r\nasync function saveCaz(){\r\n  const srs=await loadSurse('soi-plan2-cazuri');\r\n  CAZURI=imbinaListe([{salvatLa:acum(),data:CAZURI}].concat(srs));\r\n  const prag=addDays(todayIso(),-30);\r\n  CAZURI=CAZURI.filter(c=>!c.sters||(c.mod_la||'')>prag);\r\n  return save('soi-plan2-cazuri',CAZURI);\r\n}\r\nasync function saveBife(){\r\n  const srs=await loadSurse('soi-plan2-bife');\r\n  BIFE=imbinaBife([{salvatLa:acum(),data:BIFE}].concat(srs));\r\n  return save('soi-plan2-bife',BIFE);\r\n}\r\nasync function savePrag(){\r\n  const srs=await loadSurse('soi-plan2-praguri');\r\n  PRAGURI=imbinaObiect([{salvatLa:acum(),data:PRAGURI}].concat(srs),'prag-');\r\n  return save('soi-plan2-praguri',PRAGURI);\r\n}\r\nasync function saveOverrides(){\r\n  const srs=await loadSurse('soi-plan2-overrides');\r\n  OVERRIDES=imbinaObiect([{salvatLa:acum(),data:OVERRIDES}].concat(srs),'ovr-');\r\n  return save('soi-plan2-overrides',OVERRIDES);\r\n}\r\nasync function saveAbsenti(){\r\n  const srs=await loadSurse('soi-plan2-absenti');\r\n  ABSENTI=imbinaObiect([{salvatLa:acum(),data:ABSENTI}].concat(srs),'abs-');\r\n  return save('soi-plan2-absenti',ABSENTI);\r\n}\r\nasync function saveRutinaCustom(){\r\n  const srs=await loadSurse('soi-plan2-rutina-custom');\r\n  RUTINA_CUSTOM=imbinaListe([{salvatLa:acum(),data:RUTINA_CUSTOM}].concat(srs));\r\n  return save('soi-plan2-rutina-custom',RUTINA_CUSTOM);\r\n}\r\nasync function saveRutinaOff(){\r\n  const srs=await loadSurse('soi-plan2-rutina-off');\r\n  RUTINA_OFF=imbinaObiect([{salvatLa:acum(),data:RUTINA_OFF}].concat(srs),'roff-');\r\n  return save('soi-plan2-rutina-off',RUTINA_OFF);\r\n}\r\n/* strat permanent pentru sarcinile de rutină: tăiere/editare care rămân pentru\r\n   toate zilele (independent de dată), cu re-activare din editorul de rutină */\r\nasync function saveRovr(){\r\n  const srs=await loadSurse('soi-plan2-rutina-ovr');\r\n  ROVR=imbinaObiect([{salvatLa:acum(),data:ROVR}].concat(srs),'rovr-');\r\n  return save('soi-plan2-rutina-ovr',ROVR);\r\n}\r\nasync function saveExtra(){\r\n  const srs=await loadSurse('soi-plan2-extra');\r\n  EXTRA=imbinaListe([{salvatLa:acum(),data:EXTRA}].concat(srs));\r\n  const prag=addDays(todayIso(),-30);\r\n  EXTRA=EXTRA.filter(e=>!e.sters||(e.mod_la||'')>prag);\r\n  return save('soi-plan2-extra',EXTRA);\r\n}\r\nasync function loadAll(silentios){\r\n  if(!TESTAT)await testStocare();\r\n  const sTb=await loadSurse('soi-plan2-tombs');   /* primul: tombstone-urile ghidează îmbinarea celorlalte */\r\n  if(sTb.length)TOMBS=imbinaTomb([{salvatLa:acum(),data:TOMBS}].concat(sTb));\r\n  const sCz=await loadSurse('soi-plan2-cazuri');\r\n  if(sCz.length||INCARCAT)CAZURI=imbinaListe([{salvatLa:acum(),data:CAZURI}].concat(sCz));\r\n  const sEx=await loadSurse('soi-plan2-extra');\r\n  if(sEx.length||INCARCAT)EXTRA=imbinaListe([{salvatLa:acum(),data:EXTRA}].concat(sEx));\r\n  const sBf=await loadSurse('soi-plan2-bife');\r\n  if(sBf.length)BIFE=imbinaBife([{salvatLa:acum(),data:BIFE}].concat(sBf));\r\n  const sPr=await loadSurse('soi-plan2-praguri');\r\n  if(sPr.length)PRAGURI=imbinaObiect([{salvatLa:acum(),data:PRAGURI}].concat(sPr),'prag-');\r\n  const sOv=await loadSurse('soi-plan2-overrides');\r\n  if(sOv.length)OVERRIDES=imbinaObiect([{salvatLa:acum(),data:OVERRIDES}].concat(sOv),'ovr-');\r\n  const sAb=await loadSurse('soi-plan2-absenti');\r\n  if(sAb.length)ABSENTI=imbinaObiect([{salvatLa:acum(),data:ABSENTI}].concat(sAb),'abs-');\r\n  const sRc=await loadSurse('soi-plan2-rutina-custom');\r\n  if(sRc.length||INCARCAT)RUTINA_CUSTOM=imbinaListe([{salvatLa:acum(),data:RUTINA_CUSTOM}].concat(sRc));\r\n  const sRo=await loadSurse('soi-plan2-rutina-off');\r\n  if(sRo.length)RUTINA_OFF=imbinaObiect([{salvatLa:acum(),data:RUTINA_OFF}].concat(sRo),'roff-');\r\n  const sRov=await loadSurse('soi-plan2-rutina-ovr');\r\n  if(sRov.length)ROVR=imbinaObiect([{salvatLa:acum(),data:ROVR}].concat(sRov),'rovr-');\r\n  INCARCAT=true;\r\n  if(!USER){\r\n    let u=null; try{u=localStorage.getItem('soi-plan2-user');}catch(e){}\r\n    if(!u&&window.storage){try{const r=await window.storage.get('soi-plan2-user');if(r&&r.value)u=r.value;}catch(e){}}\r\n    if(u&&TOTI.indexOf(u)>=0){USER=u;document.getElementById('whoami').value=USER;}\r\n  }\r\n  verificaSarciniNoi(!!silentios);\r\n  render();\r\n  pornesteSync();\r\n  autoPreiaZilnic();\r\n}\r\nfunction setUser(u){\r\n  USER=u;\r\n  try{localStorage.setItem('soi-plan2-user',u);}catch(e){}\r\n  if(window.storage){try{window.storage.set('soi-plan2-user',u);}catch(e){}}\r\n  cereNotificari(true);\r\n  FILTRU='';render();\r\n}\r\nasync function refresh(btn){\r\n  if(btn)btn.textContent='…';\r\n  let n=0; while(PENDING>0&&n++<40)await new Promise(r=>setTimeout(r,100)); /* așteaptă salvările în curs */\r\n  await loadAll();\r\n  if(btn)btn.textContent='🔄 Actualizează';toast('Actualizat ✓');\r\n}\r\n/* sincronizare de fundal: la fiecare minut aduce modificările colegilor, fără să întrerupă editarea */\r\nlet PULS_CUNOSCUT='', ULTIMA_INTERACTIUNE=0;\r\nfunction scrieAcum(){ /* pauzăm doar cât timp cineva chiar tastează într-un câmp de text */\r\n  const a=document.activeElement;\r\n  if(!a)return false;\r\n  if(a.tagName==='TEXTAREA')return true;\r\n  if(a.tagName==='INPUT'&&/^(text|number|date|search|url|tel|email)$/i.test(a.type||'text'))return true;\r\n  return false;\r\n}\r\nasync function sincronizeaza(fortat){\r\n  if(PENDING>0||FORM||EDITCAZ||EDITEXTRA||EDITSLOT||EDITCONCEDIU||EDITRUTINA)return;\r\n  if(!fortat&&(scrieAcum()||Date.now()-ULTIMA_INTERACTIUNE<8000))return;\r\n  if(SYNC_URL){\r\n    /* mai întâi un „puls\" mic: s-a schimbat ceva de la ultima verificare? */\r\n    const p=await netGet('soi-plan2-puls');\r\n    const t=p?(p.salvatLa||''):'';\r\n    if(!fortat&&t&&t===PULS_CUNOSCUT)return;\r\n    PULS_CUNOSCUT=t;\r\n  }\r\n  await loadAll(false);\r\n}\r\nfunction pornesteSync(){\r\n  if(SYNC_PORNIT||(!window.storage&&!SYNC_URL))return; SYNC_PORNIT=true;\r\n  if(window.addEventListener){\r\n    window.addEventListener('focus',()=>sincronizeaza(true));\r\n    if(typeof document!=='undefined'&&document.addEventListener)\r\n      document.addEventListener('visibilitychange',()=>{if(!document.hidden)sincronizeaza(true);});\r\n    ['pointerdown','keydown'].forEach(ev=>window.addEventListener(ev,()=>{ULTIMA_INTERACTIUNE=Date.now();},true));\r\n  }\r\n  setInterval(()=>sincronizeaza(false),10000);\r\n}\r\n\r\n/* ================== NOTIFICĂRI SARCINI ================== */\r\nfunction vazuteKey(){return 'soi-plan2-vazut-'+slug(USER||'x');}\r\nfunction citesteVazute(){try{return JSON.parse(localStorage.getItem(vazuteKey())||'[]');}catch(e){return [];}}\r\nfunction sarciniNoiPentruMine(){\r\n  if(!USER)return [];\r\n  const vaz=citesteVazute();\r\n  return EXTRA.filter(e=>!e.sters&&e.pers===USER&&!BIFE['extra|'+e.id]&&vaz.indexOf(e.id)<0);\r\n}\r\nfunction marcheazaVazute(){\r\n  if(!USER)return;\r\n  const vaz=citesteVazute();\r\n  EXTRA.filter(e=>e.pers===USER).forEach(e=>{if(vaz.indexOf(e.id)<0)vaz.push(e.id);});\r\n  try{localStorage.setItem(vazuteKey(),JSON.stringify(vaz.slice(-400)));}catch(e){}\r\n}\r\nfunction cereNotificari(tacut){\r\n  if(!('Notification' in window)){if(!tacut)toast('Browserul nu are notificări');return;}\r\n  if(Notification.permission==='default')Notification.requestPermission().then(()=>render());\r\n  else if(!tacut)toast(Notification.permission==='granted'?'Notificările sunt pornite ✓':'Notificările sunt blocate din setările browserului');\r\n}\r\nfunction verificaSarciniNoi(cuSunet){\r\n  const noi=sarciniNoiPentruMine().filter(e=>NOTIFICATE.indexOf(e.id)<0);\r\n  if(!noi.length)return;\r\n  noi.forEach(e=>NOTIFICATE.push(e.id));\r\n  if('Notification' in window&&Notification.permission==='granted')\r\n    noi.forEach(e=>{try{new Notification((e.urgent?'🔥 URGENT — ':'')+'📌 Sarcină nouă de la '+(e.by||'un coleg'),{body:e.t+' · pentru '+e.data});}catch(err){}});\r\n  if(cuSunet){sunet();toast('📌 Ai '+noi.length+(noi.length===1?' sarcină nouă':' sarcini noi')+(noi.some(e=>e.urgent)?' — una URGENTĂ!':''));}\r\n}\r\n/* clopoțel discret când primești o sarcină */\r\nfunction sunet(){\r\n  try{\r\n    const A=window.AudioContext||window.webkitAudioContext; if(!A)return;\r\n    const ctx=new A(), o=ctx.createOscillator(), g=ctx.createGain();\r\n    o.type='sine'; o.frequency.value=880; g.gain.value=.08;\r\n    o.connect(g); g.connect(ctx.destination); o.start();\r\n    o.frequency.setValueAtTime(1175,ctx.currentTime+.12);\r\n    g.gain.exponentialRampToValueAtTime(.0001,ctx.currentTime+.45);\r\n    o.stop(ctx.currentTime+.5);\r\n  }catch(e){}\r\n}\r\n\r\n/* ================== RUTINA ZILNICĂ (o dată pe om, indiferent câte cazuri) ================== */\r\n/* bloc: 'd' = 9:00–12:00, 'p' = 12:30–15:30 */\r\nfunction rutinaBaza(iso){\r\n  const w=dow(iso); if(w<1||w>5)return [];\r\n  const g=[], act=cazIntens(iso);\r\n  /* sarcină generală, o dată pe zi */\r\n  const A=(pers,t,dur,bloc)=>g.push({pers,t,dur,bloc});\r\n  /* sarcină per caz: durata totală se împarte între cazurile active, cu un minim */\r\n  const P=(pers,tpl,durTot,bloc,min)=>{\r\n    if(!act.length)return;\r\n    act.forEach(cz=>{\r\n      const dur=Math.max(min||10,Math.round(durTot/act.length/5)*5);\r\n      g.push({pers,t:tpl.replace('{C}',cz.nume),dur,bloc,cazId:cz.id,caz:cz.nume,zile:cz.zile,ziN:diffDays(cz.start,iso)+1});\r\n    });\r\n  };\r\n  /* postări în grupuri: minimum 5 pe caz, 3 minute bucata */\r\n  const POST=pers=>{\r\n    if(!act.length){A(pers,'15 postări în grupuri Facebook — lotul propriu',45,'p');return;}\r\n    act.forEach(cz=>{\r\n      const q=Math.max(5,Math.round(15/act.length));\r\n      g.push({pers,t:q+' postări în grupuri pentru '+cz.nume,dur:Math.max(15,q*3),bloc:'p',cazId:cz.id,caz:cz.nume,zile:cz.zile,ziN:diffDays(cz.start,iso)+1});\r\n    });\r\n  };\r\n\r\n  /* --- ANDREEA: presă & firme calde --- */\r\n  P('Andreea','Pitch de presă pentru {C}: 5 redacții noi contactate',60,'d',15);\r\n  if(w===3||w===4)P('Andreea','Email de mulțumire redacțiilor care au scris despre {C}',40,'d',10);\r\n  A('Andreea','Firme calde din CRM: apeluri și emailuri de follow-up',45,'d');\r\n  POST('Andreea');\r\n  P('Andreea','3–5 link-uri media pentru {C} + tracker actualizat',40,'p',10);\r\n  A('Andreea','LinkedIn: prieteni noi țintit + răspuns la comentarii',15,'p');\r\n  A('Andreea','Prospectare: 10 companii noi cu profil potrivit + date de contact',30,'p');\r\n  A('Andreea','Reactivare donatori: 20 de mesaje personale către donatorii cazurilor anterioare',30,'p');\r\n  A('Andreea','Actualizare CRM după apeluri: etapă, următorul pas, termen',20,'p');\r\n  if(w===3)A('Andreea','Mesaj WhatsApp: anunțul campaniei noi trimis pe liste și contacte',20,'d');\r\n  if(w===5)A('Andreea','Mesaj pe grupul de WhatsApp: rezumatul săptămânii',20,'p');\r\n  if(w===3)A('Andreea','Actualizarea bazei de jurnaliști: cine scrie despre sănătate, ce contact avem',30,'p');\r\n  if(w===5)A('Andreea','Planul de presă pentru săptămâna viitoare: ce cazuri, ce redacții, ce unghi',40,'d');\r\n  if(w===5)A('Andreea','Raportul articolelor obținute săptămâna aceasta + ce a mers',30,'p');\r\n\r\n  /* --- PAULA: companii locale --- */\r\n  P('Paula','Telefoane către companii locale din zona cazului {C}',60,'d',20);\r\n  A('Paula','Search 10 companii locale noi + completare CRM',20,'d');\r\n  POST('Paula');\r\n  P('Paula','Search grupuri locale și județene pentru {C} + cerere de intrare',30,'p',10);\r\n  if(w===2)P('Paula','One-pager actualizat pentru {C} către companiile în discuție',60,'p',20);\r\n  A('Paula','LinkedIn: distribuire + interacțiune cu comentariile',15,'p');\r\n  A('Paula','40 de voluntari: trimite postarea zilei — fiecare pe Facebook + 2 grupuri',45,'p');\r\n  if(w===3)A('Paula','Voluntari: apeluri către cei mai activi 5 + recrutare de voluntari noi',30,'d');\r\n  if(w===5)A('Paula','Voluntari: mulțumire pentru săptămâna aceasta + actualizarea listei',20,'p');\r\n  A('Paula','Actualizare CRM după telefoane + lista de sunat de mâine',25,'p');\r\n  if(w===3)A('Paula','Verificare grupuri: cereri acceptate, reguli, cine e administrator',20,'p');\r\n  if(w===1||w===4)A('Paula','Documente pentru firme: contract de sponsorizare, facturi, adeverințe',30,'p');\r\n  if(w===4)A('Paula','Raport companii: câte contactate, câte au răspuns, câte au alocat',30,'p');\r\n\r\n  /* --- ȘTEFANIA: conținut social --- */\r\n  P('Ștefania','Conținut pentru {C}: foto, card, reel',80,'d',20);\r\n  if(w===2||w===5)P('Ștefania','TikTok pentru {C}: montaj și publicare',60,'d',20);\r\n  POST('Ștefania');\r\n  P('Ștefania','Story cu contorul pentru {C}',30,'p',10);\r\n  P('Ștefania','Programare postări de seară pentru {C} (Instagram, Facebook)',40,'p',10);\r\n  A('Ștefania','Răspuns la comentarii și mesaje pe conturile de social media',20,'p');\r\n  A('Ștefania','LinkedIn: o postare + adăugare prieteni noi, țintit',20,'p');\r\n  A('Ștefania','Bancă de conținut: 3 postări pregătite în avans pentru mâine',40,'p');\r\n  A('Ștefania','Cere familiilor materiale foto și video pentru zilele următoare',20,'p');\r\n  A('Ștefania','Reactivare donatori: 20 de mesaje personale către donatorii cazurilor anterioare',30,'p');\r\n  if(w===5)A('Ștefania','Planul de conținut pentru săptămâna viitoare, pe cazurile active',40,'d');\r\n  if(w===5)A('Ștefania','Analiza performanței postărilor: ce format a mers, ce nu',30,'p');\r\n\r\n  /* --- VLAD: coordonare, plăți, dezvoltare & conținut propriu --- */\r\n  A('Vlad','💳 Plăți facturi — verifică scadențele și achită ce e de plată',20,'d');\r\n  A('Vlad','Update plăți pe site',15,'d');\r\n  A('Vlad','Update baza de date Wallaxy',20,'d');\r\n  A('Vlad','Statistici Google Analytics + website: ce a mers, ce urmărim',20,'d');\r\n  A('Vlad','1 postare pe LinkedIn',15,'p');\r\n  A('Vlad','2 postări pe social media',20,'p');\r\n  A('Vlad','🤖 Răspunsuri automate prin PostJelly la 5 campanii cu impact',15,'p');\r\n  if(w===2||w===5)A('Vlad','📣 Postare mesaj comunitate pe Facebook — pagina „Salvează o inimă\" + „Vlad Plăcintă\"',15,'p');\r\n  A('Vlad','Dezvoltare generatoare + update-uri la instrumente',60,'p');\r\n  if(w>=1&&w<=3)A('Vlad','📰 Update presă scrisă pe site — după ce publică Andreea',20,'p');\r\n  if(w===1||w===4)A('Vlad','📧 Newsletter — campanie de strângere de fonduri',45,'d');\r\n  if(w===2)A('Vlad','⬆️ Încărcare caz nou (marțea)',45,'d');\r\n  if(w===2)A('Vlad','🔔 Notificare în aplicație la lansarea campaniei noi',5,'d');\r\n  if(w===4)A('Vlad','🎥 Live Zoom (diseară) — pregătire și susținere',45,'p');\r\n  if(w===5)A('Vlad','👥 Ședința de echipă: pregătire și conducere — bilanț, blocaje, ce preluăm și lansăm',30,'d');\r\n\r\n  return g;\r\n}\r\n/* sarcinile recurente proprii, adăugate din interfață (RUTINA_CUSTOM), pe zilele alese */\r\nfunction rutinaCustomZi(iso){\r\n  const w=dow(iso); if(w<1||w>5)return [];\r\n  return RUTINA_CUSTOM.filter(r=>!r.sters&&Array.isArray(r.zile)&&r.zile.indexOf(w)>=0)\r\n    .map(r=>({pers:r.pers,t:r.t,dur:+r.dur||20,bloc:r.bloc||'d',prio:r.prio||''}));\r\n}\r\n/* rutina finală = șablonul (fără cele ascunse) + sarcinile proprii adăugate */\r\nfunction rutina(iso){\r\n  return rutinaBaza(iso).filter(t=>!RUTINA_OFF[slug(t.pers)+'|'+slug(t.t)]).concat(rutinaCustomZi(iso));\r\n}\r\n\r\n/* ================== PLANUL UNUI CAZ (marginal, doar ce ține de cazul acela) ================== */\r\nfunction planCaz(cz){\r\n  const N=cz.zile, T=TIERS[N]||TIERS[30], R=cz.resp||'Paula', plan={};\r\n  const add=(d,pers,t,dur,bloc)=>{const k=addDays(cz.start,d-1);(plan[k]=plan[k]||[]).push({pers,t:t.replace('{C}',cz.nume),dur:dur||30,bloc:bloc||'d'});};\r\n\r\n  /* ZIUA 1 — preluare & lansare */\r\n  add(1,R,'Predă lui Vlad dosarul medical și verifică pagina cazului pe site',20,'d');\r\n  add(1,R,'Acord scris de la familie (foto/video) + ghidul de postare trimis pe WhatsApp',45,'d');\r\n  add(1,R,'Brief video pentru Gabriel: ce filmăm, cu cine, când — și termenul de livrare',25,'d');\r\n  add(1,'Ștefania','Pachetul vizual de lansare: foto caz, card de start, story',45,'p');\r\n  add(1,R,'Cere lui Andrei scenariile Make pentru caz: postări programate + alerte la praguri',10,'p');\r\n  add(1,'Familia','Postează cazul pe Facebook (profil personal) și îl distribuie prietenilor',0,'p');\r\n  add(1,'Familia','Trimite linkul pe WhatsApp la toate grupurile personale: familie, bloc, colegi',0,'p');\r\n  add(1,'Familia','Face lista celor 20 de oameni care sigur ajută — și îi sună pe rând',0,'p');\r\n\r\n  /* ZIUA 2 */\r\n  add(2,R,'Update la 24 de ore: sună familia, adună noutățile, pregătește textul',30,'d');\r\n  add(2,'Familia','Update la 24 de ore de la lansare',0,'p');\r\n  add(2,'Familia','Înscriere în grupurile de Facebook indicate de echipă',0,'p');\r\n\r\n  /* ZIUA 3 */\r\n  add(3,R,'Update la 48 de ore + trimiterea cazului pe grupurile locale și județene',45,'d');\r\n  add(3,R,'Alocări de la companii: apeluri de confirmare pentru cazul acesta',45,'d');\r\n  add(3,'Familia','Update campanie la 48 de ore',0,'p');\r\n  add(3,'Familia','Postare pe grupurile locale și județene',0,'p');\r\n\r\n  /* COMUNICAT DE PRESĂ */\r\n  const minPR={7:3,15:5,30:7,60:10}[N]||5;\r\n  let prZi=0;\r\n  for(let d=minPR;d<=Math.max(minPR,N-3);d++){if(dow(addDays(cz.start,d-1))===1){prZi=d;break;}}\r\n  if(!prZi)prZi=Math.min(minPR,N);\r\n  add(prZi,'Andreea','Comunicat de presă pentru caz: redactare, trimitere, follow-up telefonic',90,'d');\r\n  add(prZi,'Familia','Postează 3 link-uri media',0,'p');\r\n  for(let k=1;k<=2;k++)if(prZi+k<=N)add(prZi+k,'Familia','5 link-uri media postate',0,'p');\r\n\r\n  /* VERIFICARE PRAG 60% */\r\n  const zPrag=Math.max(3,Math.round(N*0.6));\r\n  add(zPrag,R,'⚠️ Prag 60%: semnalează-i lui Vlad unde suntem cu suma',10,'d');\r\n  add(zPrag,R,'Planul B pentru caz: relansare video, val nou de companii, ambasadori',45,'d');\r\n\r\n  /* ULTIMELE ZILE */\r\n  if(N>4){\r\n    add(N-2,R,'Cere lui Vlad newsletterul „ultima sută de metri\" și lui Gabriel varianta scurtă de final',15,'d');\r\n    add(N-2,'Ștefania','Video de urgență: cât mai lipsește',45,'d');\r\n  }\r\n\r\n  /* ZIUA FINALĂ */\r\n  add(N,R,'Confirmă cu Vlad plata către clinică și publicarea ordinelor de plată',15,'d');\r\n  add(N,R,'Cere lui Andrei emailul de mulțumire către toți donatorii campaniei',10,'p');\r\n  add(N,'Ștefania','Carduri de mulțumire pentru companii și donatori',45,'p');\r\n  add(N,R,'Cere lui Gabriel videoclipul de mulțumire pentru companiile care au susținut',10,'d');\r\n  add(N,'Andreea','Mulțumire nominală companiilor care au alocat sume',45,'d');\r\n  add(N,R,'Raportul final al cazului: sume, articole, companii, ce a mers',45,'p');\r\n  add(N,R,'Pregătește debriefingul cazului pentru ședința de vineri',20,'p');\r\n\r\n  /* --- CAZ ÎN CONTINUARE: ritm săptămânal, nu zilnic --- */\r\n  if(cz.mod==='intretinere'){\r\n    for(let d=2;d<=N;d++){\r\n      const w=dow(addDays(cz.start,d-1));\r\n      if(w===2){add(d,R,'5 postări în grupuri pentru {C}',15,'p');add(d,R,'Verificare sumă și raportare către Vlad — {C}',10,'d');\r\n        add(d,'Familia','Distribuie cazul în 3 grupuri și trimite 5 mesaje directe',0,'p');}\r\n      if(w===3)add(d,R,'Contact cu familia {C} + lista lor săptămânală pe WhatsApp',20,'d');\r\n      if(w===4){add(d,'Ștefania','Story cu contorul pentru {C}',10,'p');add(d,R,'5 postări în grupuri pentru {C}',15,'p');}\r\n      if(w===5){add(d,R,'Update săptămânal {C}: sumă, noutăți medicale, mulțumiri',25,'p');\r\n        add(d,'Familia','Update pe Facebook + mulțumiri celor care au donat',0,'p');}\r\n    }\r\n    return plan;\r\n  }\r\n\r\n  /* RECURENTE ale cazului */\r\n  for(let d=2;d<=N;d++){\r\n    const iso=addDays(cz.start,d-1), w=dow(iso), lucru=(w>=1&&w<=5);\r\n\r\n    /* --- FAMILIA: are program zilnic, nu așteaptă --- */\r\n    add(d,'Familia','Distribuie cazul în 5 grupuri în care e înscrisă',0,'p');\r\n    add(d,'Familia','10 mesaje directe către rude, prieteni, colegi — cu linkul campaniei',0,'p');\r\n    add(d,'Familia','Mulțumește nominal, în comentarii, celor care au donat ieri',0,'p');\r\n    if(d%2===0)add(d,'Familia','Filmează un clip scurt cu telefonul: cum e azi, ce urmează',0,'p');\r\n    if(d%T.upd===0)add(d,'Familia','Update pe Facebook: unde suntem cu suma, ce urmează',0,'p');\r\n    if(w===2)add(d,'Familia','Cere anunțul la locul de muncă, la școală sau la biserică',0,'p');\r\n    if(w===4)add(d,'Familia','Contactează 3 firme locale unde are cunoscuți',0,'p');\r\n    if(w===5)add(d,'Familia','Postare de mulțumire după o săptămână încărcată',0,'p');\r\n\r\n    /* --- RESPONSABILUL: mobilizează familia, o dată la două zile --- */\r\n    if(lucru&&d%2===1)add(d,R,'Mobilizarea familiei {C}: trimite pe WhatsApp lista pentru următoarele două zile',15,'d');\r\n    if(w===5)add(d,R,'Update sumă pentru caz + text de mulțumire trimis familiei',25,'p');\r\n    if(lucru&&d%2===0)add(d,R,'Contact cu familia: cum stau, ce noutăți avem de comunicat',20,'d');\r\n  }\r\n  return plan;\r\n}\r\n\r\nfunction cazIntens(iso){return cazuriActive(iso).filter(c=>(c.mod||'intens')==='intens');}\r\nfunction cazIntretinere(iso){return cazuriActive(iso).filter(c=>c.mod==='intretinere');}\r\nfunction cazuriActive(iso){\r\n  return CAZURI.filter(c=>!c.sters&&!c.gata&&diffDays(c.start,iso)+1>=1&&diffDays(c.start,iso)+1<=c.zile);\r\n}\r\nfunction sarciniZiBrut(iso){\r\n  const out=[], viitor=(iso>=todayIso());\r\n  cazuriActive(iso).forEach(cz=>{\r\n    const plan=planCaz(cz), d=diffDays(cz.start,iso)+1;\r\n    (plan[iso]||[]).forEach((t,i)=>{\r\n      if(viitor&&t.pers!=='Familia'&&BLOCATI.indexOf(t.pers)>=0)return;\r\n      out.push(Object.assign({},t,{caz:cz.nume,resp:cz.resp,cazId:cz.id,zile:cz.zile,ziN:d,key:cz.id+'|'+iso+'|'+slug(t.pers)+'-'+i}));\r\n    });\r\n  });\r\n  /* praguri atinse, cu videoclipul nefăcut — apar zilnic până sunt bifate */\r\n  if(viitor)cazuriActive(iso).forEach(cz=>{\r\n    [50,75].forEach(x=>{\r\n      const k='prag|'+cz.id+'|'+x;\r\n      if(PRAGURI[cz.id+'|prag'+x]&&!BIFE[k])\r\n        out.push({pers:'Ștefania',t:'🎬 Video '+x+'% pentru '+cz.nume+' — montaj și postare pe TikTok, Facebook și Instagram',dur:60,bloc:'d',caz:cz.nume,cazId:cz.id,zile:cz.zile,ziN:diffDays(cz.start,iso)+1,key:k});\r\n    });\r\n    /* Vlad: card de evoluție + update pe site la fiecare prag atins (25/50/75/100) */\r\n    [25,50,75,100].forEach(x=>{\r\n      const kv='pragv|'+cz.id+'|'+x;\r\n      if(PRAGURI[cz.id+'|prag'+x]&&!BIFE[kv])\r\n        out.push({pers:'Vlad',t:'📊 Card evoluție '+x+'% pentru '+cz.nume+' + update pe site cu pragul atins',dur:20,bloc:'d',caz:cz.nume,cazId:cz.id,zile:cz.zile,ziN:diffDays(cz.start,iso)+1,key:kv});\r\n    });\r\n  });\r\n  /* sarcini date de Vlad */\r\n  EXTRA.filter(e=>!e.sters&&e.data===iso).forEach(e=>{const pr=prioExtra(e);out.push({pers:e.pers,prio:pr,t:(pr==='urg'?'🔥 ':pr==='imp'?'⭐ ':'')+'📌 '+e.t+' — de la '+(e.by||'Vlad'),dur:+e.dur||30,bloc:e.bloc||'d',caz:'',cazId:'extra',zile:0,key:'extra|'+e.id});});\r\n  rutina(iso).forEach(t=>{\r\n    if(viitor&&t.cazId&&BLOCATI.indexOf(t.pers)>=0)return;\r\n    out.push(Object.assign({caz:'',cazId:'gen',zile:0},t,{key:'rut|'+iso+'|'+slug(t.pers)+'|'+(t.cazId&&t.cazId!=='gen'?t.cazId+'|':'')+slug(t.t).slice(0,44)}));\r\n  });\r\n  /* concediu: sarcinile unei responsabile absente merg la celelalte responsabile;\r\n     ale unui absent fără înlocuitor (ex. coordonator) se ascund cât e plecat */\r\n  const subs=RESPONSABILI.filter(r=>!esteAbsent(r,iso));\r\n  out.forEach(t=>{\r\n    if(t.pers==='Familia'||!esteAbsent(t.pers,iso))return;\r\n    if(RESPONSABILI.indexOf(t.pers)>=0&&subs.length){t.inlocuit=t.pers;t.pers=subs[Math.abs(hashStr(t.key))%subs.length];}\r\n  });\r\n  /* strat de suprascriere per zi (anulare/editare) + ascunderea celor rămași absenți */\r\n  return out.filter(t=>{\r\n    if(esteAbsent(t.pers,iso)&&t.pers!=='Familia')return false;\r\n    let o=OVERRIDES[t.key];\r\n    if(isRutKey(t.key)){const po=ROVR[rovrKey(t.key)]; if(po)o=po;} /* rutina: permanent > per-zi */\r\n    if(o&&o.sters)return false;\r\n    if(o){if(o.t!=null)t.t=o.t;if(typeof o.dur==='number'&&o.dur>0)t.dur=o.dur;t.editat=true;}\r\n    return true;\r\n  });\r\n}\r\n/* programul de 5 ore: alegem ce încape în zi, în ordinea urgenței; restul nu se programează */\r\nfunction alegePentruZi(iso){\r\n  const all=sarciniZiBrut(iso), chei=new Set(), taiate=[];\r\n  const pers=[...new Set(all.map(t=>t.pers))];\r\n  pers.forEach(p=>{\r\n    const ale=all.filter(t=>t.pers===p);\r\n    const fix=t=>t.cazId==='gen'||t.cazId==='extra'||t.pers==='Familia'||String(t.key).indexOf('prag|')===0;\r\n    const fixe=ale.filter(fix), rest=ale.filter(t=>!fix(t));\r\n    fixe.forEach(t=>chei.add(t.key));\r\n    let buget=PROGRAM_MAX-fixe.reduce((s,t)=>s+t.dur,0);\r\n    const pri=t=>(t.zile&&TIERS[t.zile])?TIERS[t.zile].pr:5;\r\n    rest.sort((a,b)=>pri(a)-pri(b)||b.dur-a.dur);\r\n    rest.forEach(t=>{if(t.dur<=buget){chei.add(t.key);buget-=t.dur;}else taiate.push(t);});\r\n  });\r\n  return {chei,taiate};\r\n}\r\nfunction sarciniZi(iso){const sel=alegePentruZi(iso).chei;return sarciniZiBrut(iso).filter(t=>sel.has(t.key));}\r\n\r\n/* ================== ÎMPACHETARE PE ORE, PE DOUĂ BLOCURI ================== */\r\nfunction orarPers(iso,pers){\r\n  const all=sarciniZi(iso).filter(t=>t.pers===pers);\r\n  const pri=t=>t.zile?TIERS[t.zile].pr:(t.prio==='urg'?0:t.prio==='imp'?1:5);\r\n  const srt=(a,b)=>pri(a)-pri(b)||b.dur-a.dur;\r\n  const dim=all.filter(t=>t.bloc==='d').sort(srt), dupa=all.filter(t=>t.bloc!=='d').sort(srt);\r\n  const rez=[],over=[];\r\n  const pune=(lista,bloc,spill)=>{\r\n    let cur=bloc[0];\r\n    lista.forEach(t=>{\r\n      if(cur+t.dur<=bloc[1]){rez.push(Object.assign({},t,{de:cur,la:cur+t.dur}));cur+=t.dur;}\r\n      else spill.push(t);\r\n    });\r\n    return cur;\r\n  };\r\n  const spillD=[],spillP=[],B1=bloc1For(iso);\r\n  pune(dim,B1,spillD);\r\n  let cur2=pune(dupa.concat(spillD).sort(srt),BLOC2,spillP);\r\n  /* ce n-a încăput după-amiaza încearcă în golul rămas dimineața */\r\n  let curD=rez.filter(t=>t.de<MASA[0]).reduce((m,t)=>Math.max(m,t.la),B1[0]);\r\n  spillP.forEach(t=>{\r\n    if(curD+t.dur<=B1[1]){rez.push(Object.assign({},t,{de:curD,la:curD+t.dur}));curD+=t.dur;}\r\n    else over.push(t);\r\n  });\r\n  /* golurile rămase se umplu cu muncă utilă, nu se lasă albe */\r\n  const sugestie=(pers,iso,idx)=>{\r\n    const nr=(RESTP&&RESTP[pers])||0;\r\n    if(nr>0)return 'Recuperează din restanțe — mai ai '+nr+' de bifat';\r\n    const L=FLEX[pers]||[]; if(!L.length)return 'Timp de lucru liber';\r\n    const z=Math.floor(new Date(iso+'T12:00:00')/864e5);\r\n    return L[(z+idx)%L.length];\r\n  };\r\n  const flexSlot=(de,la,idx)=>({pers,t:sugestie(pers,iso,idx),dur:la-de,bloc:idx?'p':'d',de,la,flex:true,caz:'',cazId:'flex',zile:0,key:'flex|'+iso+'|'+slug(pers)+'|'+idx});\r\n  let capD=rez.filter(t=>t.de<MASA[0]).reduce((m,t)=>Math.max(m,t.la),B1[0]);\r\n  if(B1[1]-capD>=15)rez.push(flexSlot(capD,B1[1],0));\r\n  let capP=rez.filter(t=>t.de>=BLOC2[0]).reduce((m,t)=>Math.max(m,t.la),BLOC2[0]);\r\n  /* ultimul sfert de oră din zi = planificarea zilei de mâine: urgent, apoi important */\r\n  const URG=Math.min(25,BLOC2[1]-capP), urgDe=BLOC2[1]-(URG>0?URG:0);\r\n  if(urgDe-capP>=15)rez.push(flexSlot(capP,urgDe,1)); /* golul dinaintea planificării → timp liber */\r\n  if(URG>=10){\r\n    const maine=ziuaLucrUrm(iso);\r\n    const nUI=EXTRA.filter(e=>!e.sters&&e.pers===pers&&e.data===maine&&(prioExtra(e)==='urg'||prioExtra(e)==='imp')).length;\r\n    rez.push({pers:pers,t:'⚡ Planifică mâine — alege/scrie ce faci la prima oră (urgent, apoi important)'+(nUI?' · '+nUI+' pregătite':''),dur:BLOC2[1]-urgDe,bloc:'p',de:urgDe,la:BLOC2[1],urgblock:true,maine:maine,caz:'',cazId:'urg',zile:0,key:'urg|'+iso+'|'+slug(pers)});\r\n  }\r\n  rez.sort((a,b)=>a.de-b.de);\r\n  const incarcare=all.reduce((s,t)=>s+t.dur,0);\r\n  return {rez,over,incarcare};\r\n}\r\nfunction incarcareZi(iso,pers){return orarPers(iso,pers).incarcare;}\r\n\r\n/* ================== BIFE & RESTANȚE ================== */\r\nfunction tick(key,on,box){\r\n  if(!USER){alert('Alege-ți numele din dreapta sus.');box.checked=!on;return;}\r\n  if(on){BIFE[key]={by:USER,at:new Date().toLocaleString('ro-RO',{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'}),ts:acum()};revine('bifa-'+key);}\r\n  else{delete BIFE[key];marcheazaSters('bifa-'+key);}\r\n  saveBife();render();toast(on?'Bifat ✓':'Debifat');\r\n}\r\nfunction restante(){\r\n  const azi=todayIso(),out=[],selC={};\r\n  /* se păstrează doar restanțele din ziua lucrătoare anterioară — tot ce e mai vechi de 48 de ore dispare singur */\r\n  let lim=addDays(azi,-1);while(dow(lim)===0||dow(lim)===6)lim=addDays(lim,-1);\r\n  const selFor=iso=>selC[iso]||(selC[iso]=alegePentruZi(iso).chei);\r\n  CAZURI.filter(c=>!c.sters&&!c.gata).forEach(cz=>{\r\n    const plan=planCaz(cz);\r\n    Object.keys(plan).sort().forEach(iso=>{\r\n      if(iso>=azi||iso<lim)return;\r\n      plan[iso].forEach((t,i)=>{\r\n        const key=cz.id+'|'+iso+'|'+slug(t.pers)+'-'+i;\r\n        /* sarcinile care n-au intrat în programul de 5 ore al zilei nu devin restanțe */\r\n        if(!BIFE[key]&&selFor(iso).has(key))out.push(Object.assign({},t,{iso,caz:cz.nume,zile:cz.zile,key}));\r\n      });\r\n    });\r\n  });\r\n  out.sort((a,b)=>a.iso<b.iso?-1:1);\r\n  return out;\r\n}\r\n\r\n/* ================== RANDARE ================== */\r\nfunction esteCazReal(id){return !!id&&['extra','gen','flex'].indexOf(id)<0&&String(id).indexOf('prag')!==0;}\r\nfunction mergiLaCaz(id){setView('caz');setTimeout(function(){const el=document.getElementById('caz-'+id);if(el){el.scrollIntoView({behavior:'smooth',block:'center'});el.style.boxShadow='0 0 0 3px var(--amber)';setTimeout(function(){el.style.boxShadow='';},1400);}},60);}\r\nfunction tagCaz(t){\r\n  if(!t.caz)return '<span class=\"tag tgen\">rutină</span>';\r\n  const inner=esc(t.caz)+' · Z'+t.ziN+'/'+t.zile;\r\n  if(esteCazReal(t.cazId))return '<span class=\"tag '+TIERS[t.zile].cls+'\" style=\"cursor:pointer\" title=\"Vezi cazul\" onclick=\"mergiLaCaz(\\''+t.cazId+'\\')\">'+inner+' ↗</span>';\r\n  return '<span class=\"tag '+TIERS[t.zile].cls+'\">'+inner+'</span>';\r\n}\r\nfunction setView(v){VIEW=v;if(v==='extra')marcheazaVazute();['zi','caz','final','rest','extra','fisa'].forEach(x=>document.getElementById('tab_'+x).classList.toggle('on',x===v));render();}\r\nfunction setZi(v){ZI=v;render();}\r\nfunction render(){\r\n  BLOCATI=[];RESTP={};\r\n  const r=restante(),bd=document.getElementById('restbdg');\r\n  r.forEach(t=>{RESTP[t.pers]=(RESTP[t.pers]||0)+1;});\r\n  BLOCATI=Object.keys(RESTP).filter(p=>RESTP[p]>PRAG_RESTANTE);\r\n  bd.textContent=r.length;bd.style.display=r.length?'inline-block':'none';\r\n  let al='';\r\n  if(TESTAT&&!ST_LOCAL&&!ST_CLOUD&&!ST_NET)\r\n    al+='<div class=\"alarm\" style=\"background:var(--red-deep)\">⚠️ <b>Aici datele NU se pot salva.</b> Fereastra în care e deschis instrumentul blochează orice stocare — tot ce lucrezi se pierde la închidere. '\r\n      +'Soluția: descarcă fișierul pe calculator și deschide-l cu dublu-clic, direct în browser (Chrome/Edge). Acolo salvarea automată funcționează la fiecare modificare. '\r\n      +'Până atunci, apasă 💾 Copie de siguranță înainte să închizi.</div>';\r\n  const noiPtMine=sarciniNoiPentruMine();\r\n  if(noiPtMine.length&&VIEW!=='extra')\r\n    al+='<div class=\"alarm\" style=\"background:var(--purple)\">📌 <b>'+noiPtMine.length+(noiPtMine.length===1?' sarcină nouă':' sarcini noi')+' pentru tine</b> — de la '+[...new Set(noiPtMine.map(e=>e.by||'?'))].map(esc).join(', ')\r\n      +'<button class=\"btn small\" onclick=\"setView(\\'extra\\')\">Vezi-le</button></div>';\r\n  if(r.length)\r\n    al+='<div class=\"alarm\">🔔 <b>'+r.length+' sarcini neîndeplinite</b> din zilele trecute'\r\n     +(USER?' — dintre care <b>'+r.filter(x=>x.pers===USER).length+'</b> ale tale':'')\r\n     +'<button class=\"btn small\" onclick=\"setView(\\'rest\\')\">Vezi restanțele</button></div>'\r\n     +(BLOCATI.length?'<div class=\"alarm\" style=\"background:var(--red-deep)\">🚫 <b>'+BLOCATI.map(esc).join(', ')+'</b> — peste '+PRAG_RESTANTE+' restanțe. Cazurile nu mai generează sarcini noi pentru ei; rutina zilnică rămâne. Se deblochează automat sub '+PRAG_RESTANTE+'.</div>':'');\r\n  const exR=USER?EXTRA.filter(e=>!e.sters&&e.pers===USER&&e.data<todayIso()&&!BIFE['extra|'+e.id]):[];\r\n  if(exR.length&&VIEW!=='extra')\r\n    al+='<div class=\"alarm\" style=\"background:var(--amber)\">📌 <b>'+exR.length+(exR.length===1?' sarcină primită restantă':' sarcini primite restante')+'</b> — nefăcute din zilele trecute<button class=\"btn small\" onclick=\"setView(\\'extra\\')\">Vezi-le</button></div>';\r\n  document.getElementById('alarmbox').innerHTML=al;\r\n  const tr=document.getElementById('toolrow');\r\n  if(VIEW==='zi')tr.innerHTML='<button class=\"btn small\" onclick=\"setZi(\\''+addDays(ZI,-1)+'\\')\">←</button>'\r\n    +'<input type=\"date\" value=\"'+ZI+'\" onchange=\"setZi(this.value)\">'\r\n    +'<button class=\"btn small\" onclick=\"setZi(\\''+addDays(ZI,1)+'\\')\">→</button>'\r\n    +'<button class=\"btn small\" onclick=\"setZi(\\''+todayIso()+'\\')\">Azi</button>'\r\n    +'<button class=\"btn\" onclick=\"refresh(this)\">🔄 Actualizează</button>';\r\n  else if(VIEW==='caz')tr.innerHTML='<button class=\"btn primary\" onclick=\"FORM=!FORM;render()\">➕ Caz nou</button><button class=\"btn\" onclick=\"refresh(this)\">🔄 Actualizează</button>';\r\n  else tr.innerHTML='<button class=\"btn\" onclick=\"refresh(this)\">🔄 Actualizează</button>';\r\n  tr.innerHTML+='<button class=\"btn small\" onclick=\"SETARI=!SETARI;render()\" title=\"Sincronizare între calculatoare\">⚙️</button>'\r\n    +'<span class=\"mini\" id=\"autosv\" style=\"'+((ST_LOCAL||ST_CLOUD||ST_NET||!TESTAT)?'':'color:var(--red-deep);font-weight:700')+'\">'+stareText()+'</span><span style=\"flex:1\"></span>'\r\n    +'<button class=\"btn small\" onclick=\"salveazaProiect()\" title=\"Descarcă o copie de siguranță — datele se salvează oricum automat, la fiecare modificare\">💾 Copie de siguranță</button>'\r\n    +'<button class=\"btn small\" onclick=\"document.getElementById(\\'fisier\\').click()\">📂 Încarcă</button>'\r\n    +'<button class=\"btn small\" onclick=\"raportPdf()\">📄 Raport PDF</button>'\r\n    +'<button class=\"btn small\" onclick=\"raportWord()\">📄 Word</button>';\r\n  const o=document.getElementById('out');\r\n  const eb=document.getElementById('extrabdg');\r\n  const viit=USER?EXTRA.filter(e=>!e.sters&&e.pers===USER&&!BIFE['extra|'+e.id]).length\r\n                 :EXTRA.filter(e=>!e.sters&&e.data>=todayIso()&&!BIFE['extra|'+e.id]).length;\r\n  eb.textContent=viit;eb.style.display=viit?'inline-block':'none';\r\n  o.innerHTML=(SETARI?randSetari():'')+(VIEW==='zi'?randZi():VIEW==='caz'?randCazuri():VIEW==='final'?randFinalizate():VIEW==='rest'?randRestante():VIEW==='extra'?randExtra():randFise());\r\n}\r\n\r\n/* ================== SINCRONIZARE ÎNTRE CALCULATOARE ================== */\r\nfunction randSetari(){\r\n  const st=ST_NET?'<span style=\"color:var(--green);font-weight:700\">🌐 conectat — toate calculatoarele cu acest link văd aceleași date</span>'\r\n        :SYNC_URL?'<span style=\"color:var(--red-deep);font-weight:700\">❌ linkul nu răspunde — verifică-l sau internetul</span>'\r\n        :'<span style=\"color:var(--amber);font-weight:700\">neconfigurat — fiecare calculator lucrează separat</span>';\r\n  return '<div class=\"card\" style=\"border-color:var(--blue)\"><div class=\"chead\"><b>⚙️ Sincronizare între calculatoare</b><span class=\"sub\">'+st+'</span>'\r\n    +'<span class=\"right\"><button class=\"btn small\" onclick=\"SETARI=false;render()\">Închide</button></span></div>'\r\n    +'<div class=\"frow\"><label>Link bază de date</label>'\r\n    +'<input type=\"text\" id=\"sync_url\" value=\"'+esc(SYNC_URL)+'\" placeholder=\"https://…firebasedatabase.app/plan-cazuri-XXXX\" style=\"flex:1;min-width:280px\">'\r\n    +'<button class=\"btn primary small\" onclick=\"setSyncUrl()\">Salvează & testează</button></div>'\r\n    +'<div class=\"frow mini\" id=\"sync_msg\" style=\"border:none;padding-top:0\">Același link se lipește o singură dată pe fiecare calculator din echipă. După aceea, tot ce lucrează oricine se salvează automat pentru toți — bife, cazuri, sume, sarcini.</div>'\r\n    +'<details style=\"padding:10px 15px 14px;font-size:12.5px;color:var(--muted)\"><summary style=\"cursor:pointer;font-weight:700;color:var(--ink)\">Cum se obține linkul — ghid pentru Andrei (~10 minute, gratuit)</summary>'\r\n    +'<ol style=\"margin:10px 0 0 18px;line-height:1.7\">'\r\n    +'<li>Intră pe <b>console.firebase.google.com</b> cu contul Google al asociației → <b>Add project</b> → nume: <i>salveaza-o-inima-plan</i> → dezactivează Google Analytics → Create.</li>'\r\n    +'<li>În meniul din stânga: <b>Build → Realtime Database → Create database</b> → alege <b>Belgium (europe-west1)</b> → <b>Start in locked mode</b> → Enable.</li>'\r\n    +'<li>Deschide fila <b>Rules</b> și înlocuiește tot cu (schimbă <i>XXXX</i> cu un cod lung inventat de tine, gen <i>k7fq2m</i>):<br>'\r\n    +'<code style=\"display:block;background:#F1ECE2;border-radius:8px;padding:8px;margin:6px 0;font-size:11.5px\">{ \"rules\": { \"plan-cazuri-XXXX\": { \".read\": true, \".write\": true } } }</code>'\r\n    +'apoi <b>Publish</b>.</li>'\r\n    +'<li>Copiază adresa bazei din fila <b>Data</b> (arată ca <i>https://salveaza-o-inima-plan-default-rtdb.europe-west1.firebasedatabase.app</i>), adaugă la final <b>/plan-cazuri-XXXX</b> și lipește linkul complet în câmpul de mai sus, pe fiecare calculator.</li>'\r\n    +'</ol>'\r\n    +'<p style=\"margin-top:8px\">⚠️ De știut: oricine are linkul exact poate citi și modifica datele — păstrați-l doar în echipă, nu-l publicați. Planul gratuit Firebase e mai mult decât suficient pentru acest instrument.</p></details></div>';\r\n}\r\nasync function setSyncUrl(){\r\n  const v=(document.getElementById('sync_url').value||'').trim();\r\n  try{localStorage.setItem('soi-plan2-sync-url',v);}catch(e){}\r\n  SYNC_URL=v;\r\n  const el=document.getElementById('sync_msg');\r\n  if(!v){ST_NET=false;if(el)el.textContent='Sincronizarea prin internet e oprită — se salvează doar pe acest calculator.';arataAutosave();return;}\r\n  if(el)el.textContent='Se testează linkul…';\r\n  const ok=await netSet('soi-plan2-test',JSON.stringify(infasoara('1')));\r\n  ST_NET=ok;\r\n  if(ok){\r\n    toast('🌐 Conectat — se aduc datele echipei…');\r\n    await loadAll();\r\n    pornesteSync();\r\n    SETARI=true;render();\r\n    toast('🌐 Sincronizarea funcționează ✓');\r\n  }else{\r\n    if(el)el.innerHTML='<b style=\"color:var(--red-deep)\">❌ Linkul nu răspunde.</b> Verifică: începe cu https://, se termină cu numele nodului (fără .json), iar regulile din Firebase sunt publicate exact pentru acel nume.';\r\n    arataAutosave();\r\n  }\r\n}\r\n\r\nfunction randZi(){\r\n  const w=dow(ZI), lucru=(w>=1&&w<=5), active=cazuriActive(ZI);\r\n  let h='<div class=\"info\">📆 <b>'+fmtZi(ZI)+'</b> · '+(active.length?active.length+' campanii active: '+active.map(c=>esc(c.nume)+' <span class=\"mini\">(resp. '+esc(c.resp)+')</span>').join(', '):'nicio campanie activă')+'</div>';\r\n  if(!lucru)h+='<div class=\"warn\">Weekend — apar doar sarcinile familiei.</div>';\r\n  /* Gabriel/Andrei nu văd grila/agendele fetelor; fetele nu văd sarcinile lui Gabriel/Andrei. Vlad vede tot. */\r\n  const euExtern=eExtern(USER), euFata=eFata(USER);\r\n  if(!euExtern){\r\n    h+='<div class=\"grid\">'+ECHIPA.map(p=>{\r\n      const {rez,over,incarcare}=orarPers(ZI,p), tot=rez.length+over.length;\r\n      const d=rez.concat(over).filter(t=>BIFE[t.key]).length;\r\n      const proc=Math.round(incarcare/PROGRAM_MAX*100);\r\n      const cls=proc>100?'over':proc>85?'full':'';\r\n      return '<div class=\"stat '+(FILTRU===p?'on':'')+'\" onclick=\"FILTRU=FILTRU===\\''+p+'\\'?\\'\\':\\''+p+'\\';render()\">'\r\n        +'<div class=\"who\">'+p+'</div><div class=\"nums\">'+d+'<small> / '+tot+'</small></div>'\r\n        +'<div class=\"pbar\"><i class=\"'+cls+'\" style=\"width:'+Math.min(100,proc)+'%\"></i></div>'\r\n        +'<div class=\"mini\">'+Math.round(incarcare/60*10)/10+'h din 5h</div></div>';\r\n    }).join('')+'</div>';\r\n  }\r\n\r\n  /* sarcinile punctuale ale colegilor din afara programului de fundraising */\r\n  const altii=TOTI.filter(p=>{\r\n    if(ECHIPA.indexOf(p)>=0) return false;\r\n    if(euExtern) return p===USER; /* Gabriel vede doar ale lui */\r\n    if(euFata) return false; /* fetele nu văd Gabriel/Andrei */\r\n    return true; /* Vlad / nesetat: vede pe toți externii */\r\n  }).sort((a,b)=>(a===USER?-1:0)-(b===USER?-1:0));\r\n  altii.forEach(p=>{\r\n    const ale=EXTRA.filter(e=>!e.sters&&e.data===ZI&&e.pers===p);\r\n    if(!ale.length)return;\r\n    const gata=ale.filter(e=>BIFE['extra|'+e.id]).length;\r\n    h+='<div class=\"card\"><div class=\"chead\"><b>'+esc(p)+'</b><span class=\"sub\">sarcini punctuale primite azi</span><span class=\"right mini\">'+gata+'/'+ale.length+' bifate</span></div>';\r\n    ale.forEach(e=>{const b=BIFE['extra|'+e.id];\r\n      h+='<div class=\"slot '+(b?'done':'')+'\"><div class=\"hh\">'+(e.bloc==='d'?'dimineața':'după-amiaza')+'</div>'\r\n        +'<input type=\"checkbox\" '+(b?'checked':'')+' onchange=\"tick(\\'extra|'+e.id+'\\',this.checked,this)\">'\r\n        +'<div class=\"bd\">📌 '+esc(e.t)+' <span class=\"mini\">· '+e.dur+' min · de la '+esc(e.by||'?')+'</span>'\r\n        +(b?'<span class=\"byline\">✓ '+esc(b.by)+' · '+b.at+'</span>':'')+'</div></div>';});\r\n    h+='</div>';\r\n  });\r\n\r\n  let cine;\r\n  if(FILTRU){\r\n    /* nu lăsăm pe cineva să filtreze pe o persoană pe care n-ar trebui s-o vadă */\r\n    if(euExtern && FILTRU!==USER) cine=[USER];\r\n    else if(euFata && eExtern(FILTRU)) cine=[USER].concat(FETELE.filter(p=>p!==USER));\r\n    else cine=[FILTRU];\r\n  } else if(euExtern){\r\n    cine=[USER]; /* Gabriel/Andrei: doar agenda proprie, fără fete */\r\n  } else if(USER){\r\n    cine=[USER].concat(ECHIPA.filter(p=>p!==USER));\r\n  } else {\r\n    cine=ECHIPA.slice();\r\n  }\r\n  if(euFata) cine=cine.filter(p=>!eExtern(p));\r\n  cine.forEach(p=>{\r\n    const abs=esteAbsent(p,ZI);\r\n    const concEditor=(EDITCONCEDIU===p)?randConcediu(p):'';\r\n    const rutEditor=(EDITRUTINA===p)?randRutinaEditor(p):'';\r\n    const concBtn='<button class=\"btn small\" onclick=\"editConcediu(\\''+p+'\\')\" title=\"Perioade de concediu\">'+(abs?'🏖 În concediu':'🏖 Concediu')+'</button>';\r\n    const rutBtn='<button class=\"btn small\" onclick=\"editRutina(\\''+p+'\\')\" title=\"Editează sarcinile recurente\">🔁 Rutină</button>';\r\n    if(abs){\r\n      h+='<div class=\"card\" style=\"opacity:.8\"><div class=\"chead\"><b>'+p+'</b><span class=\"sub\">'+(ROL[p]||'')+'</span><span class=\"right\">'+concBtn+' '+rutBtn+'</span></div>'\r\n       +'<div class=\"slot break\" style=\"background:var(--teal-soft)\"><div class=\"hh\">🏖</div><div class=\"bd\" style=\"color:var(--teal)\"><b>În concediu azi</b> — sarcinile pe cazuri merg automat la celelalte colege.</div></div>'\r\n       +concEditor+rutEditor+'</div>';\r\n      return;\r\n    }\r\n    const {rez,over,incarcare}=orarPers(ZI,p);\r\n    const taiateP=alegePentruZi(ZI).taiate.filter(t=>t.pers===p).length;\r\n    const done=rez.concat(over).filter(t=>BIFE[t.key]).length;\r\n    h+='<div class=\"card\"><div class=\"chead\"><b>'+p+'</b><span class=\"sub\">'+ROL[p]+'</span><span class=\"right mini\">'+done+'/'+(rez.length+over.length)+' bifate · '+Math.round(incarcare/60*10)/10+'h din 5h '+concBtn+' '+rutBtn+'</span></div>'+concEditor+rutEditor;\r\n    if(taiateP)h+='<div class=\"slot break\"><div class=\"hh\">⚖️</div><div class=\"bd\">Program plin — ziua e limitată la 5 ore, așa că '+taiateP+(taiateP===1?' sarcină':' sarcini')+' din cazurile mai puțin urgente nu au intrat azi în program (și nu devin restanțe).</div></div>';\r\n    if(!lucru){h+='<div class=\"empty\">Weekend — fără program de birou.</div></div>';return;}\r\n    h+='<div class=\"slot break\"><div class=\"hh\">'+hhmm(CITIT[0])+'–'+hhmm(CITIT[1])+'</div><div class=\"bd\">📖 Citit cărți, cu o cafea fierbinte</div></div>';\r\n    if(w===ZI_SEDINTA)h+='<div class=\"slot break\" style=\"background:var(--teal-soft)\"><div class=\"hh\">'+hhmm(SEDINTA[0])+'–'+hhmm(SEDINTA[1])+'</div><div class=\"bd\" style=\"color:var(--teal)\">👥 Ședința echipei: bilanțul săptămânii, cine e blocat, ce preluăm și ce lansăm săptămâna viitoare</div></div>';\r\n    if(BLOCATI.indexOf(p)>=0)h+='<div class=\"slot over\"><div class=\"hh\">blocat</div><div class=\"bd\"><b>'+RESTP[p]+' restanțe</b> — cazurile nu-ți mai dau sarcini noi până cobori sub '+PRAG_RESTANTE+'. Rutina zilnică rămâne. <a href=\"#\" onclick=\"setView(\\'rest\\');return false\" style=\"color:var(--red-deep)\">Recuperează acum →</a></div></div>';\r\n    let masaPusa=false;\r\n    rez.forEach(t=>{\r\n      if(!masaPusa&&t.de>=MASA[0]){h+='<div class=\"slot break\"><div class=\"hh\">'+hhmm(MASA[0])+'–'+hhmm(MASA[1])+'</div><div class=\"bd\">🍽 Pauză de masă</div></div>';masaPusa=true;}\r\n      if(t.urgblock){h+=randPlanMaine(t,p);return;}\r\n      const b=BIFE[t.key];\r\n      const edit=!t.flex&&!t.urgblock&&t.key;\r\n      h+='<div class=\"slot '+(b?'done':'')+(t.flex?' flex':'')+'\"'+(t.urgblock?' style=\"border-left:4px solid var(--red-deep);background:var(--red-soft)\"':'')+'><div class=\"hh\">'+hhmm(t.de)+'–'+hhmm(t.la)+'</div>'\r\n        +'<input type=\"checkbox\" '+(b?'checked':'')+' onchange=\"tick(\\''+t.key+'\\',this.checked,this)\">'\r\n        +'<div class=\"bd\">'+(t.urgblock?'':(t.flex?'<span class=\"tag tflex\">timp liber</span>':tagCaz(t)))+esc(t.t)+(t.inlocuit?' <span class=\"tag\" style=\"background:var(--teal-soft);color:var(--teal)\">preluat de la '+esc(t.inlocuit)+'</span>':'')+(t.editat?' <span class=\"mini\">· modificată</span>':'')+(b?'<span class=\"byline\">✓ '+esc(b.by)+' · '+b.at+'</span>':'')+'</div>'\r\n        +(edit?'<button class=\"btn small\" onclick=\"editSlot(\\''+t.key+'\\')\" title=\"Modifică / înlocuiește\">✏️</button><button class=\"btn small\" onclick=\"amanaSlot(\\''+t.key+'\\')\" title=\"Amână pe mâine\">⏭</button><button class=\"btn small\" onclick=\"anuleazaSlot(\\''+t.key+'\\')\" title=\"Anulează sarcina\">✕</button>':'')\r\n        +'</div>';\r\n      if(edit&&EDITSLOT===t.key)h+=slotEditor(t);\r\n    });\r\n    if(!masaPusa)h+='<div class=\"slot break\"><div class=\"hh\">'+hhmm(MASA[0])+'–'+hhmm(MASA[1])+'</div><div class=\"bd\">🍽 Pauză de masă</div></div>';\r\n    if(!rez.length)h+='<div class=\"empty\">Nimic programat astăzi.</div>';\r\n    h+='<div class=\"slot break\"><div class=\"hh\">'+hhmm(INCHIDERE[0])+'–'+hhmm(INCHIDERE[1])+'</div><div class=\"bd\">✅ Închiderea zilei: bifează programul, notează ce a rămas, pregătește ziua de mâine</div></div>';\r\n    over.forEach(t=>{const b=BIFE[t.key];const edit=!!t.key;\r\n      h+='<div class=\"slot over '+(b?'done':'')+'\"><div class=\"hh\">nu încape</div>'\r\n        +'<input type=\"checkbox\" '+(b?'checked':'')+' onchange=\"tick(\\''+t.key+'\\',this.checked,this)\">'\r\n        +'<div class=\"bd\">'+tagCaz(t)+esc(t.t)+(t.inlocuit?' <span class=\"tag\" style=\"background:var(--teal-soft);color:var(--teal)\">preluat de la '+esc(t.inlocuit)+'</span>':'')+(t.editat?' <span class=\"mini\">· modificată</span>':'')+' <span class=\"mini\">— peste 8:30–15:30, mută la alt coleg sau altă zi</span></div>'\r\n        +(edit?'<button class=\"btn small\" onclick=\"editSlot(\\''+t.key+'\\')\" title=\"Modifică / înlocuiește\">✏️</button><button class=\"btn small\" onclick=\"amanaSlot(\\''+t.key+'\\')\" title=\"Amână pe mâine\">⏭</button><button class=\"btn small\" onclick=\"anuleazaSlot(\\''+t.key+'\\')\" title=\"Anulează sarcina\">✕</button>':'')\r\n        +'</div>';\r\n      if(edit&&EDITSLOT===t.key)h+=slotEditor(t);});\r\n    h+='</div>';\r\n  });\r\n\r\n  const fam=sarciniZi(ZI).filter(t=>t.pers==='Familia');\r\n  if(fam.length){\r\n    cazuriActive(ZI).forEach(cz=>{\r\n      const ale=fam.filter(t=>t.cazId===cz.id); if(!ale.length)return;\r\n      const gata=ale.filter(t=>BIFE[t.key]).length;\r\n      h+='<div class=\"card\"><div class=\"chead\"><b>Familia lui '+esc(cz.nume)+'</b>'\r\n        +'<span class=\"tag trsp\">trimite '+esc(cz.resp)+'</span>'\r\n        +(cz.parinti?'<span class=\"mini\">'+esc(cz.parinti)+'</span>':'')\r\n        +(cz.telefon?'<span class=\"mini\">📞 '+esc(cz.telefon)+'</span>':'')\r\n        +(cz.fb?'<span class=\"mini\"><a href=\"'+esc(cz.fb)+'\" target=\"_blank\">Facebook mama</a></span>':'')\r\n        +'<span class=\"sub\">lista de azi, pe WhatsApp — '+esc(cz.resp)+' verifică mâine ce s-a făcut</span>'\r\n        +'<span class=\"right mini\">'+gata+'/'+ale.length+'</span></div>';\r\n      ale.forEach(t=>{const b=BIFE[t.key];\r\n        h+='<div class=\"slot '+(b?'done':'')+'\"><div class=\"hh\">oricând</div><input type=\"checkbox\" '+(b?'checked':'')+' onchange=\"tick(\\''+t.key+'\\',this.checked,this)\">'\r\n          +'<div class=\"bd\">'+esc(t.t)+(b?'<span class=\"byline\">✓ '+esc(b.by)+' · '+b.at+'</span>':'')+'</div></div>';});\r\n      if(gata===0)h+='<div class=\"slot over\"><div class=\"hh\">atenție</div><div class=\"bd\">Familia n-a bifat nimic azi. '+esc(cz.resp)+', sună-i.</div></div>';\r\n      h+='</div>';\r\n    });\r\n  }\r\n  return h;\r\n}\r\n\r\nfunction randCazuri(){\r\n  const nLuna=intensiveLunaCurenta().length, nInt=CAZURI.filter(c=>!c.sters&&!c.gata&&(c.mod||'intens')==='intens').length, nCon=CAZURI.filter(c=>!c.sters&&!c.gata&&c.mod==='intretinere').length;\r\n  let h='<div class=\"'+(nLuna>=MAX_CAZ?'warn':'info')+'\">🎯 <b>Cazuri noi preluate în '+fmtLuna(todayIso())+': '+nLuna+' / '+MAX_CAZ+'</b> · în lucru acum: '+nInt+' intensive, '+nCon+' în continuare. '\r\n    +(nLuna>=MAX_CAZ?'Norma lunii e atinsă. Următoarele preluări, din '+fmtLuna(lunaUrm())+'.':'Mai poți prelua '+(MAX_CAZ-nLuna)+' cazuri noi luna aceasta.')\r\n    +' <button class=\"btn small\" onclick=\"preiaToate(this)\">⟳ Preia sumele de pe site</button></div>';\r\n  if(FORM){\r\n    h+='<div class=\"card\"><div class=\"chead\"><b>Caz nou</b></div>'\r\n      +'<div class=\"frow\"><label>Nume</label><input type=\"text\" id=\"f_nume\" placeholder=\"ex: Sara M.\" style=\"flex:1;min-width:160px\">'\r\n      +'<label>Start</label><input type=\"date\" id=\"f_start\" value=\"'+todayIso()+'\">'\r\n      +'<label>Termen</label><select id=\"f_zile\" onchange=\"previzualizare()\">'\r\n      +Object.keys(TIERS).map(z=>'<option value=\"'+z+'\">'+z+' zile · '+TIERS[z].lab+'</option>').join('')+'</select>'\r\n      +'<label>Responsabil</label><select id=\"f_resp\" onchange=\"previzualizare()\">'+RESPONSABILI.map(r=>'<option>'+r+'</option>').join('')+'</select>'\r\n      +'<label>Ritm</label><select id=\"f_mod\" onchange=\"previzualizare()\"><option value=\"intens\">Nou · intensiv</option><option value=\"intretinere\">Vechi · în continuare</option></select>'\r\n      +'<label>Obiectiv (€)</label><input type=\"number\" id=\"f_tinta\" placeholder=\"euro\" style=\"width:110px\">'\r\n      +'<label>Părinți</label><input type=\"text\" id=\"f_parinti\" placeholder=\"nume și prenume\" style=\"width:180px\">'\r\n      +'<label>Localitate</label><input type=\"text\" id=\"f_localitate\" placeholder=\"ex: Botoșani\" style=\"width:140px\">'\r\n      +'<label>Județ</label><input type=\"text\" id=\"f_judet\" placeholder=\"ex: Botoșani\" style=\"width:130px\">'\r\n      +'<label>Link site</label><input type=\"text\" id=\"f_link\" placeholder=\"https://salveazaoinima.ro/…\" style=\"width:210px\">'\r\n      +'<button class=\"btn primary\" onclick=\"adaugaCaz()\">Adaugă</button>'\r\n      +'<button class=\"btn\" onclick=\"FORM=false;render()\">Renunț</button></div>'\r\n      +'<div id=\"prev\"></div></div>';\r\n  }\r\n  const vizibile=CAZURI.filter(c=>!c.sters&&!c.gata);\r\n  const nFin=CAZURI.filter(c=>!c.sters&&c.gata).length;\r\n  if(nFin)h+='<div class=\"info\">✅ '+nFin+(nFin===1?' caz finalizat':' cazuri finalizate')+' — le găsești în tabul <b>Finalizate</b>. <button class=\"btn small\" onclick=\"setView(\\'final\\')\">Vezi-le</button></div>';\r\n  if(!vizibile.length)return h+'<div class=\"empty\">Niciun caz în lucru.</div>';\r\n  vizibile.forEach(cz=>{\r\n    const T=TIERS[cz.zile],d=diffDays(cz.start,todayIso())+1,ram=cz.zile-d+1;\r\n    h+='<div class=\"card\" id=\"caz-'+cz.id+'\"'+(cz.gata?' style=\"opacity:.55\"':'')+'><div class=\"chead\"><b>'+esc(cz.nume)+'</b>'\r\n      +'<span class=\"tag '+T.cls+'\">'+T.lab+' · '+cz.zile+' zile</span>'\r\n      +'<span class=\"tag trsp\">resp. '+esc(cz.resp)+'</span>'\r\n      +(cz.localitate||cz.judet?'<span class=\"tag tgen\">📍 '+esc([cz.localitate,cz.judet].filter(Boolean).join(', '))+'</span>':'')\r\n      +'<span class=\"tag '+((cz.mod||'intens')==='intens'?'t7':'tgen')+'\">'+((cz.mod||'intens')==='intens'?'🔥 intensiv':'🔁 în continuare')+'</span>'\r\n      +'<span class=\"sub\">start '+fmtZi(cz.start)+(cz.gata?' · încheiat':(d<1?' · începe peste '+(1-d)+' zile':(ram>0?' · ziua '+d+', mai sunt '+ram+' zile':' · termen depășit')))+'</span>'\r\n      +'<span class=\"right\"><select onchange=\"schimbaResp(\\''+cz.id+'\\',this.value)\">'+RESPONSABILI.map(r=>'<option '+(r===cz.resp?'selected':'')+'>'+r+'</option>').join('')+'</select>'\r\n      +'<button class=\"btn small\" onclick=\"EDITCAZ=EDITCAZ===\\''+cz.id+'\\'?\\'\\':\\''+cz.id+'\\';render()\" title=\"Corectează numele, startul sau termenul\">✏️ Editează</button>'\r\n      +'<button class=\"btn small\" onclick=\"toggleMod(\\''+cz.id+'\\')\">'+((cz.mod||'intens')==='intens'?'🔁 Trec în continuare':'🔥 Trec intensiv')+'</button>'\r\n      +'<label class=\"btn small\" style=\"display:inline-flex;align-items:center;gap:6px;cursor:pointer;'+(cz.gata?'background:var(--green-soft);border-color:var(--green);color:var(--green);font-weight:700':'')+'\"><input type=\"checkbox\" '+(cz.gata?'checked':'')+' onchange=\"toggleGata(\\''+cz.id+'\\')\" style=\"accent-color:var(--green);width:16px;height:16px;margin:0\">'+(cz.gata?'Caz finalizat':'Finalizare caz')+'</label>'\r\n      +'<button class=\"btn small\" onclick=\"stergeCaz(\\''+cz.id+'\\')\">✕</button></span></div>';\r\n    if(EDITCAZ===cz.id){\r\n      h+='<div class=\"frow\" style=\"background:#FDFBF6\"><label>Nume</label><input type=\"text\" id=\"ed_nume\" value=\"'+esc(cz.nume)+'\" style=\"flex:1;min-width:170px\">'\r\n        +'<label>Start</label><input type=\"date\" id=\"ed_start\" value=\"'+esc(cz.start)+'\">'\r\n        +'<label>Termen</label><select id=\"ed_zile\">'+Object.keys(TIERS).map(z=>'<option value=\"'+z+'\"'+(+z===+cz.zile?' selected':'')+'>'+z+' zile · '+TIERS[z].lab+'</option>').join('')+'</select>'\r\n        +'<label>Localitate</label><input type=\"text\" id=\"ed_localitate\" value=\"'+esc(cz.localitate||'')+'\" placeholder=\"ex: Botoșani\" style=\"width:140px\">'\r\n        +'<label>Județ</label><input type=\"text\" id=\"ed_judet\" value=\"'+esc(cz.judet||'')+'\" placeholder=\"ex: Botoșani\" style=\"width:130px\">'\r\n        +'<label>Link site</label><input type=\"text\" id=\"ed_link\" value=\"'+esc(cz.link||'')+'\" placeholder=\"https://salveazaoinima.ro/…\" style=\"flex:1;min-width:210px\">'\r\n        +'<button class=\"btn primary small\" onclick=\"salveazaEditCaz(\\''+cz.id+'\\')\">Salvează corecturile</button>'\r\n        +'<button class=\"btn small\" onclick=\"EDITCAZ=\\'\\';render()\">Renunț</button>'\r\n        +'<span class=\"mini\" style=\"flex-basis:100%\">Numele se schimbă peste tot, fără să se piardă nimic. Dacă schimbi startul sau termenul, programul se recalculează — bifele de pe zilele mutate ajung la restanțe.</span></div>';\r\n    }\r\n    const proc=procCaz(cz);\r\n    h+='<div class=\"freqhead\">Familia</div>'\r\n      +'<div class=\"frow\"><label>Părinți</label><input type=\"text\" value=\"'+esc(cz.parinti||'')+'\" placeholder=\"nume și prenume\" style=\"flex:1;min-width:190px\" onchange=\"setCamp(\\''+cz.id+'\\',\\'parinti\\',this.value)\">'\r\n      +'<label>Telefon</label><input type=\"text\" value=\"'+esc(cz.telefon||'')+'\" placeholder=\"07…\" style=\"width:130px\" onchange=\"setCamp(\\''+cz.id+'\\',\\'telefon\\',this.value)\"></div>'\r\n      +'<div class=\"frow\" style=\"border:none;padding-top:0\"><label>Localitate</label><input type=\"text\" value=\"'+esc(cz.localitate||'')+'\" placeholder=\"ex: Botoșani\" style=\"flex:1;min-width:150px\" onchange=\"setCamp(\\''+cz.id+'\\',\\'localitate\\',this.value)\">'\r\n      +'<label>Județ</label><input type=\"text\" value=\"'+esc(cz.judet||'')+'\" placeholder=\"ex: Botoșani\" style=\"width:150px\" onchange=\"setCamp(\\''+cz.id+'\\',\\'judet\\',this.value)\"></div>'\r\n      +'<div class=\"frow\" style=\"border:none;padding-top:0\"><label>Email</label><input type=\"text\" value=\"'+esc(cz.email||'')+'\" placeholder=\"email\" style=\"flex:1;min-width:160px\" onchange=\"setCamp(\\''+cz.id+'\\',\\'email\\',this.value)\">'\r\n      +'<label>Facebook mama</label><input type=\"text\" value=\"'+esc(cz.fb||'')+'\" placeholder=\"link profil\" style=\"flex:1;min-width:160px\" onchange=\"setCamp(\\''+cz.id+'\\',\\'fb\\',this.value)\"></div>'\r\n      +'<div class=\"freqhead\">Obiectiv financiar</div>'\r\n      +'<div class=\"fin\">'\r\n      +'<div class=\"finhead\"><span class=\"sum\" id=\"sm'+cz.id+'\">'+eur(cz.strans||0)+'</span><span class=\"din\">din '+eur(cz.tinta||0)+'</span>'\r\n      +'<span class=\"pct '+clsProc(proc)+'\" id=\"pc'+cz.id+'\">'+proc+'%</span></div>'\r\n      +'<div class=\"track\"><div class=\"fill'+(proc>=100?' done':'')+'\" id=\"fl'+cz.id+'\" style=\"width:'+Math.min(100,proc)+'%\"></div>'\r\n      +[25,50,75].map(x=>'<i class=\"mk\" style=\"left:'+x+'%\"></i>').join('')+'<div class=\"shine\"></div></div>'\r\n      +'<div class=\"marks\">'+[25,50,75,100].map(x=>'<span class=\"'+(proc>=x?'hit':'')+'\" style=\"left:'+x+'%\">'+(proc>=x?'✓ ':'')+x+'%</span>').join('')+'</div>'\r\n      +'<input type=\"range\" class=\"fs\" min=\"0\" max=\"'+Math.max(1,cz.tinta||100)+'\" step=\"50\" value=\"'+(cz.strans||0)+'\" '\r\n      +'oninput=\"finLive(\\''+cz.id+'\\',this.value,'+Math.max(1,cz.tinta||1)+')\" onchange=\"setSuma(\\''+cz.id+'\\',this.value)\">'\r\n      +'<div class=\"frow\" style=\"border:none;padding:8px 0 0\"><label>Strâns</label><input type=\"number\" value=\"'+(cz.strans||0)+'\" style=\"width:120px\" onchange=\"setSuma(\\''+cz.id+'\\',this.value)\"> €'\r\n      +'<label>Obiectiv</label><input type=\"number\" value=\"'+(cz.tinta||0)+'\" style=\"width:120px\" onchange=\"setCamp(\\''+cz.id+'\\',\\'tinta\\',+this.value)\"> €'\r\n      +(cz.link?'<button class=\"btn small\" onclick=\"preiaSuma(\\''+cz.id+'\\',this)\">⟳ Preia de pe site</button><a href=\"'+esc(cz.link)+'\" target=\"_blank\" rel=\"noopener\" class=\"mini\" style=\"color:var(--muted)\">pagina cazului ↗</a>'\r\n               :'<span class=\"mini\">pune linkul cazului la ✏️ Editează și suma se preia singură de pe site</span>')\r\n      +'</div></div>'\r\n      +'<div class=\"freqhead\">Praguri — se aprind singure din sumă</div><div class=\"prag\">'\r\n      +[25,50,75,100].map(x=>{const k=cz.id+'|prag'+x, vid=BIFE['prag|'+cz.id+'|'+x], areVideo=(x===50||x===75);\r\n        return '<button class=\"pragbtn '+(PRAGURI[k]?'on':'')+'\" onclick=\"togglePrag(\\''+k+'\\')\">'+x+'%'+(PRAGURI[k]?(areVideo?(vid?' ✓ video':' · video de făcut'):' ✓'):'')+'</button>';}).join('')+'</div>'\r\n      +'<div class=\"frow mini\">Când suma trece de 50% sau 75%, Ștefania primește automat în agendă sarcina de video (TikTok, Facebook, Instagram) și apare alertă până e bifată.</div>'\r\n      +notiteHtml(cz)+'</div>';\r\n  });\r\n  return h;\r\n}\r\n/* ============ PAGINA CAZURILOR FINALIZATE ============ */\r\nfunction randFinalizate(){\r\n  const fin=CAZURI.filter(c=>!c.sters&&c.gata);\r\n  if(!fin.length)return '<div class=\"empty\">Niciun caz finalizat încă. Când bifezi „Finalizare caz\" în tabul Cazuri, cazul se mută aici.</div>';\r\n  let h='<div class=\"info\">✅ <b>'+fin.length+(fin.length===1?' caz finalizat':' cazuri finalizate')+'</b> — sarcinile lor au fost scoase din program și din restanțe. De aici le poți redeschide oricând.</div>';\r\n  fin.forEach(cz=>{\r\n    const proc=procCaz(cz);\r\n    h+='<div class=\"card\"><div class=\"chead\"><b>'+esc(cz.nume)+'</b>'\r\n      +'<span class=\"tag '+TIERS[cz.zile].cls+'\">'+TIERS[cz.zile].lab+' · '+cz.zile+' zile</span>'\r\n      +'<span class=\"tag trsp\">resp. '+esc(cz.resp)+'</span>'\r\n      +(cz.localitate||cz.judet?'<span class=\"tag tgen\">📍 '+esc([cz.localitate,cz.judet].filter(Boolean).join(', '))+'</span>':'')\r\n      +'<span class=\"tag '+clsProc(proc)+'\" style=\"padding:4px 9px\">'+eur(cz.strans||0)+' / '+eur(cz.tinta||0)+' · '+proc+'%</span>'\r\n      +'<span class=\"sub\">start '+fmtZi(cz.start)+' · încheiat</span>'\r\n      +'<span class=\"right\">'\r\n      +(cz.link?'<a href=\"'+esc(cz.link)+'\" target=\"_blank\" rel=\"noopener\" class=\"btn small\">pagina cazului ↗</a>':'')\r\n      +'<button class=\"btn small\" onclick=\"toggleGata(\\''+cz.id+'\\')\">↩︎ Redeschide</button>'\r\n      +'<button class=\"btn small\" onclick=\"stergeCaz(\\''+cz.id+'\\')\">✕</button></span></div>'\r\n      +notiteHtml(cz)+'</div>';\r\n  });\r\n  return h;\r\n}\r\n/* ============ NOTIȚE PENTRU COLEGI, PE FIECARE CAZ ============ */\r\nfunction notiteHtml(cz){\r\n  const nts=(cz.notite||[]).filter(n=>!n.sters);\r\n  let h='<div class=\"freqhead\">📒 Notițe pentru colegi'+(nts.length?' · '+nts.length:'')+'</div>';\r\n  nts.slice().reverse().forEach(n=>{\r\n    h+='<div class=\"slot\"><div class=\"hh\">'+esc(String(n.la||'').slice(8,10)+'.'+String(n.la||'').slice(5,7))+'</div>'\r\n      +'<div class=\"bd\">'+esc(n.text)+'<span class=\"byline\">— '+esc(n.de||'?')+'</span></div>'\r\n      +((n.de===USER||USER==='Vlad')?'<button class=\"btn small\" onclick=\"stergeNotita(\\''+cz.id+'\\',\\''+n.id+'\\')\">✕</button>':'')\r\n      +'</div>';\r\n  });\r\n  h+='<div class=\"frow\" style=\"border:none\"><input type=\"text\" id=\"nt_'+cz.id+'\" placeholder=\"Ceva important pentru colegi — ex: familia răspunde doar după 14:00; mâine sunați la clinică\" style=\"flex:1;min-width:220px\" onkeydown=\"if(event.key===\\'Enter\\')adaugaNotita(\\''+cz.id+'\\')\">'\r\n    +'<button class=\"btn primary small\" onclick=\"adaugaNotita(\\''+cz.id+'\\')\">Adaugă notița</button></div>';\r\n  return h;\r\n}\r\nfunction adaugaNotita(id){\r\n  const c=CAZURI.find(x=>x.id===id); if(!c)return;\r\n  const el=document.getElementById('nt_'+id), txt=((el&&el.value)||'').trim();\r\n  if(!txt){alert('Scrie întâi notița.');return;}\r\n  (c.notite=c.notite||[]).push({id:uid(),de:USER||'?',la:acum(),text:txt});\r\n  c.mod_la=acum(); saveCaz(); render(); toast('Notiță salvată — o văd toți colegii ✓');\r\n}\r\nfunction stergeNotita(cid,nid){\r\n  const c=CAZURI.find(x=>x.id===cid); if(!c||!c.notite)return;\r\n  const n=c.notite.find(x=>x.id===nid); if(n)n.sters=true;\r\n  c.mod_la=acum(); saveCaz(); render();\r\n}\r\nfunction previzualizare(){\r\n  const el=document.getElementById('prev'); if(!el)return;\r\n  const z=+document.getElementById('f_zile').value, resp=document.getElementById('f_resp').value, st=document.getElementById('f_start').value||todayIso();\r\n  const md=(document.getElementById('f_mod')||{}).value||'intens';\r\n  const fictiv={id:'__prev',nume:'(caz nou)',zile:z,start:st,resp,mod:md,gata:false};\r\n  CAZURI.push(fictiv);\r\n  let h='<div class=\"loadbar\">';\r\n  ECHIPA.forEach(p=>{\r\n    let s=0,n=0;\r\n    for(let i=0;i<7;i++){const iso=addDays(st,i);if(dow(iso)<1||dow(iso)>5)continue;s+=incarcareZi(iso,p);n++;}\r\n    const med=n?s/n:0, proc=Math.round(med/PROGRAM_MAX*100);\r\n    h+='<div class=\"lb '+(proc>100?'bad':proc>85?'mid':'ok')+'\"><b>'+p+'</b>'+Math.round(med/60*10)/10+'h/zi · '+proc+'%</div>';\r\n  });\r\n  CAZURI=CAZURI.filter(c=>c.id!=='__prev');\r\n  h+='</div><div class=\"frow mini\">Încărcarea medie pe primele 7 zile, dacă adaugi acest caz. Peste 100% înseamnă că sarcini vor ieși din program — schimbă responsabilul sau termenul.</div>';\r\n  el.innerHTML=h;\r\n}\r\nfunction adaugaCaz(){\r\n  const nume=document.getElementById('f_nume').value.trim();\r\n  if(!nume){alert('Scrie numele cazului.');return;}\r\n  const md=(document.getElementById('f_mod')||{}).value||'intens';\r\n  const nLuna=intensiveLunaCurenta().length;\r\n  if(md==='intens'&&nLuna>=MAX_CAZ){\r\n    const lista=intensiveLunaCurenta().map(c=>c.nume+' (resp. '+c.resp+')').join(', ');\r\n    if(!confirm('În '+fmtLuna(todayIso())+' ai preluat deja '+MAX_CAZ+' cazuri noi: '+lista+'.\\n\\nRegula e maximum '+MAX_CAZ+' de cazuri noi pe lună. Următoarele preluări, din '+fmtLuna(lunaUrm())+'.\\n\\nAdaugi totuși peste normă?'))return;\r\n  }\r\n  const resp=document.getElementById('f_resp').value;\r\n  if(BLOCATI.indexOf(resp)>=0&&!confirm(resp+' are '+RESTP[resp]+' restanțe și e blocat. Cazul se adaugă, dar sarcinile lui nu vor apărea până nu recuperează. Continui?'))return;\r\n  CAZURI.push({id:uid(),nume,zile:+document.getElementById('f_zile').value,start:document.getElementById('f_start').value||todayIso(),resp,mod:(document.getElementById('f_mod')||{}).value||'intens',tinta:+(document.getElementById('f_tinta')||{}).value||0,strans:0,parinti:((document.getElementById('f_parinti')||{}).value||'').trim(),localitate:((document.getElementById('f_localitate')||{}).value||'').trim(),judet:((document.getElementById('f_judet')||{}).value||'').trim(),email:'',telefon:'',fb:'',link:((document.getElementById('f_link')||{}).value||'').trim(),gata:false,mod_la:acum()});\r\n  saveCaz();FORM=false;render();toast('Caz adăugat ✓');\r\n}\r\nfunction schimbaResp(id,v){const c=CAZURI.find(x=>x.id===id);if(c){c.resp=v;c.mod_la=acum();saveCaz();render();toast('Responsabil: '+v);}}\r\nfunction salveazaEditCaz(id){\r\n  const c=CAZURI.find(x=>x.id===id); if(!c)return;\r\n  const nume=document.getElementById('ed_nume').value.trim();\r\n  if(!nume){alert('Numele cazului nu poate rămâne gol.');return;}\r\n  c.nume=nume;\r\n  c.start=document.getElementById('ed_start').value||c.start;\r\n  c.zile=+document.getElementById('ed_zile').value||c.zile;\r\n  c.link=(document.getElementById('ed_link').value||'').trim();\r\n  c.localitate=((document.getElementById('ed_localitate')||{}).value||'').trim();\r\n  c.judet=((document.getElementById('ed_judet')||{}).value||'').trim();\r\n  c.mod_la=acum();\r\n  saveCaz();EDITCAZ='';render();toast('Caz corectat ✓');\r\n}\r\nfunction toggleMod(id){const c=CAZURI.find(x=>x.id===id);if(c){c.mod=(c.mod||'intens')==='intens'?'intretinere':'intens';c.mod_la=acum();saveCaz();render();toast(c.mod==='intens'?'Ritm intensiv':'Ritm redus');}}\r\nfunction toggleGata(id){const c=CAZURI.find(x=>x.id===id);if(c){c.gata=!c.gata;c.mod_la=acum();saveCaz();render();toast(c.gata?'✅ '+c.nume+' finalizat — sarcinile lui au fost scoase din program și din restanțe':'↩︎ '+c.nume+' redeschis — programul se regenerează');}}\r\nfunction stergeCaz(id){if(!confirm('Ștergi cazul și programul lui?'))return;const c=CAZURI.find(x=>x.id===id);if(c){c.sters=true;c.mod_la=acum();}saveCaz();render();toast('Șters');}\r\nconst eur=n=>(+n||0).toLocaleString('ro-RO')+' €';\r\nconst clsProc=p=>p>=100?'p100':p>=75?'p75':p>=50?'p50':p>=25?'p25':'p0';\r\nfunction finLive(id,val,tinta){\r\n  const proc=Math.min(999,Math.round(val/tinta*100));\r\n  const sm=document.getElementById('sm'+id), pc=document.getElementById('pc'+id), fl=document.getElementById('fl'+id);\r\n  if(sm)sm.textContent=eur(val);\r\n  if(pc){pc.textContent=proc+'%';pc.className='pct '+clsProc(proc);}\r\n  if(fl){fl.style.width=Math.min(100,proc)+'%';fl.className='fill'+(proc>=100?' done':'');}\r\n}\r\nfunction procCaz(cz){return cz.tinta?Math.min(999,Math.round((cz.strans||0)/cz.tinta*100)):0;}\r\nfunction setCamp(id,camp,val){const c=CAZURI.find(x=>x.id===id);if(!c)return;c[camp]=val;c.mod_la=acum();saveCaz();render();toast('Salvat ✓');}\r\nfunction setSuma(id,val,auto){\r\n  const c=CAZURI.find(x=>x.id===id);if(!c)return;\r\n  const nou=+val||0;\r\n  /* preluarea automată/de pe site nu SCADE suma: o sumă de caz doar crește, iar o\r\n     valoare mai mică vine de la un scrape stal — ar șterge pragurile (video) și ar\r\n     da înapoi progresul. Editarea manuală (din câmp) poate pune orice. */\r\n  if(auto && nou < (c.strans||0)) return;\r\n  c.strans=nou;c.mod_la=acum();const proc=procCaz(c);\r\n  let noi=[];\r\n  [25,50,75,100].forEach(x=>{const k=c.id+'|prag'+x;\r\n    if(proc>=x&&!PRAGURI[k]){PRAGURI[k]={auto:true,at:todayIso()};noi.push(x);}\r\n    if(proc<x&&PRAGURI[k]&&PRAGURI[k].auto){delete PRAGURI[k];marcheazaSters('prag-'+k);}\r\n  });\r\n  saveCaz();savePrag();render();\r\n  const cuVideo=noi.filter(x=>x===50||x===75);\r\n  toast(noi.length?'🎉 '+c.nume+' a atins '+noi.join('% și ')+'%'+(cuVideo.length?' — video pentru Ștefania!':' ✓'):'Sumă actualizată ✓');\r\n}\r\n/* ============ PRELUAREA SUMELOR DE PE SITE ============ */\r\nfunction numarSuma(x){\r\n  if(x==null||x==='')return null;\r\n  const v=Math.round(parseFloat(String(x).replace(/[^0-9,\\.]/g,'').replace(/\\./g,'').replace(',','.')));\r\n  return isFinite(v)&&v>0?v:null;\r\n}\r\nasync function iaText(u,ms){\r\n  const opts={cache:'no-store'};\r\n  let ctrl=null;\r\n  if(typeof AbortController==='function'){ctrl=new AbortController();opts.signal=ctrl.signal;setTimeout(()=>{try{ctrl.abort();}catch(e){}},ms||12000);}\r\n  const r=await fetch(u,opts);\r\n  if(!r||!r.ok)return null;\r\n  return await r.text();\r\n}\r\nasync function preiaSume(url,cazId){\r\n  if(typeof fetch!=='function')return null;\r\n  /* 1. releul propriu al asociației (Make): extrage sumele el însuși și răspunde cu ele */\r\n  try{\r\n    const t=await iaText('https://hook.eu1.make.com/itcilr7k2cbofioivbsop3t9xkt8t3xe?caz='+encodeURIComponent(cazId||'')+'&url='+encodeURIComponent(url),20000);\r\n    if(t){try{const j=JSON.parse(t);const rez={strans:numarSuma(j.strans),tinta:numarSuma(j.tinta)};if(rez.strans!=null)return rez;}catch(e){}}\r\n  }catch(e){}\r\n  /* 2. releul scrie oricum rezultatul și în Firebase — canalul care sigur funcționează */\r\n  if(cazId&&SYNC_URL){\r\n    try{\r\n      await new Promise(rz=>setTimeout(rz,1500));\r\n      const t=await iaText(urlCheie('soi-plan2-sume-site/'+cazId),12000);\r\n      if(t){const j=JSON.parse(t);\r\n        if(j&&j.la&&(Date.now()/1000-(+j.la))<300){\r\n          const rez={strans:numarSuma(j.strans),tinta:numarSuma(j.tinta)};\r\n          if(rez.strans!=null)return rez;\r\n        }}\r\n    }catch(e){}\r\n  }\r\n  /* 3. rezervă: citire directă + servicii publice, cu extragere locală */\r\n  const cai=[url,\r\n    'https://api.allorigins.win/raw?url='+encodeURIComponent(url),\r\n    'https://corsproxy.io/?url='+encodeURIComponent(url)];\r\n  for(const u of cai){\r\n    try{const t=await iaText(u,12000);\r\n        if(t){const rez=extrageSume(t);if(rez.strans!=null)return rez;}}\r\n    catch(e){}\r\n  }\r\n  return null;\r\n}\r\nfunction extrageSume(html){\r\n  /* pe site simbolul euro e scris ca &euro; in codul paginii, nu ca semnul in sine */\r\n  const txt=String(html).replace(/<[^>]*>/g,' ').replace(/\\s+/g,' ');\r\n  const EU='(?:\\u20ac|&euro;|&#8364;|EUR)';\r\n  const st=txt.match(new RegExp('(?:Suma\\\\s+primit[a\\u0103]|Amount\\\\s+received)[\\\\s\\\\S]{0,600}?(\\\\d[\\\\d.,]*)\\\\s*'+EU,'i'));\r\n  const nc=txt.match(new RegExp('(?:Necesari|Needed)[\\\\s\\\\S]{0,600}?(\\\\d[\\\\d.,]*)\\\\s*'+EU,'i'));\r\n  return {strans:st?numarSuma(st[1]):null,tinta:nc?numarSuma(nc[1]):null};\r\n}\r\nasync function preiaSuma(id,btn,tacut){\r\n  const c=CAZURI.find(x=>x.id===id); if(!c)return false;\r\n  if(!c.link){if(!tacut)toast('Adaugă întâi linkul cazului la ✏️ Editează');return false;}\r\n  if(btn)btn.textContent='…';\r\n  const r=await preiaSume(c.link,c.id);\r\n  if(btn)btn.textContent='⟳ Preia de pe site';\r\n  if(!r){if(!tacut)toast('❌ Nu am putut citi suma de pe pagina '+c.nume+' — verifică linkul și internetul');return false;}\r\n  if(r.tinta)c.tinta=r.tinta;\r\n  setSuma(id,r.strans,true);   // auto: nu scade suma corectată manual\r\n  return true;\r\n}\r\nasync function preiaToate(btn){\r\n  const cu=CAZURI.filter(c=>!c.sters&&!c.gata&&c.link);\r\n  if(!cu.length){toast('Niciun caz activ nu are încă linkul de pe site (se pune la ✏️ Editează)');return;}\r\n  if(btn){btn.disabled=true;btn.textContent='Se preiau sumele…';}\r\n  let ok=0; const esuate=[];\r\n  for(const c of cu){if(await preiaSuma(c.id,null,true))ok++; else esuate.push(c.nume);}\r\n  if(btn){btn.disabled=false;btn.textContent='⟳ Preia sumele de pe site';}\r\n  toast(esuate.length?('Preluate '+ok+' din '+cu.length+'. Nu am reușit la: '+esuate.join(', ')+' — verifică linkurile lor.')\r\n                     :('Sume preluate de pe site: '+ok+' din '+cu.length+' cazuri ✓'));\r\n}\r\n/* o dată pe zi, sumele se aduc singure de pe site — o singură dată pe toată echipa,\r\n   nu pe fiecare calculator (data ultimei preluări e păstrată în baza comună) */\r\nasync function autoPreiaZilnic(){\r\n  if(typeof fetch!=='function')return;\r\n  if(!CAZURI.some(c=>!c.sters&&!c.gata&&c.link))return;\r\n  try{\r\n    const ult=await load('soi-plan2-suma-auto');\r\n    if(ult===todayIso())return;\r\n    await save('soi-plan2-suma-auto',todayIso());\r\n  }catch(e){return;}\r\n  setTimeout(()=>preiaToate(null),2500);\r\n}\r\nfunction togglePrag(k){if(PRAGURI[k]){delete PRAGURI[k];marcheazaSters('prag-'+k);}else{PRAGURI[k]={by:USER||'?',at:todayIso()};revine('prag-'+k);}savePrag();render();}\r\n/* Concediu pe perioade: ABSENTI[p] = listă de {de, pana}. E absent într-o zi\r\n   dacă acea zi cade în vreo perioadă — se activează singur în intervalul ales. */\r\nfunction esteAbsent(p,iso){const r=ABSENTI[p];if(!Array.isArray(r))return false;iso=iso||ZI;return r.some(x=>x&&x.de&&x.pana&&iso>=x.de&&iso<=x.pana);}\r\nfunction editConcediu(p){EDITCONCEDIU=EDITCONCEDIU===p?'':p;render();}\r\nfunction adaugaConcediu(p,sl){\r\n  const de=(document.getElementById('conc_de_'+sl)||{}).value||'', pana=(document.getElementById('conc_pana_'+sl)||{}).value||'';\r\n  if(!de||!pana){alert('Alege ambele date: de la și până la.');return;}\r\n  if(pana<de){alert('„Până la\" nu poate fi înainte de „de la\".');return;}\r\n  if(!Array.isArray(ABSENTI[p]))ABSENTI[p]=[];\r\n  ABSENTI[p].push({de:de,pana:pana,by:USER||'?',at:todayIso()});\r\n  revine('abs-'+p);\r\n  saveAbsenti();render();toast('Concediu '+esc(p)+': '+de+' → '+pana);\r\n}\r\nfunction stergeConcediu(p,idx){\r\n  if(!Array.isArray(ABSENTI[p]))return;\r\n  ABSENTI[p].splice(idx,1);\r\n  if(!ABSENTI[p].length){delete ABSENTI[p];marcheazaSters('abs-'+p);}\r\n  saveAbsenti();render();toast('Perioadă de concediu ștearsă');\r\n}\r\nfunction randConcediu(p){\r\n  const sl=slug(p), r=Array.isArray(ABSENTI[p])?ABSENTI[p]:[];\r\n  let h='<div class=\"card\" style=\"border-color:var(--teal)\"><div class=\"chead\"><b>🏖 Concediu — '+esc(p)+'</b><span class=\"right\"><button class=\"btn small\" onclick=\"editConcediu(\\''+p+'\\')\">Închide</button></span></div>';\r\n  if(r.length)h+=r.map((x,i)=>'<div class=\"slot\"><div class=\"bd\">'+fmtZi(x.de)+' → '+fmtZi(x.pana)+((ZI>=x.de&&ZI<=x.pana)?' <span class=\"tag\" style=\"background:var(--teal-soft);color:var(--teal)\">activ acum</span>':'')+'</div><button class=\"btn small\" onclick=\"stergeConcediu(\\''+p+'\\','+i+')\" title=\"Șterge perioada\">✕</button></div>').join('');\r\n  else h+='<div class=\"mini\" style=\"padding:6px 2px\">Nicio perioadă de concediu setată.</div>';\r\n  h+='<div class=\"frow\" style=\"border:none\"><label>De la</label><input type=\"date\" id=\"conc_de_'+sl+'\">'\r\n   +'<label>Până la</label><input type=\"date\" id=\"conc_pana_'+sl+'\">'\r\n   +'<button class=\"btn small\" onclick=\"adaugaConcediu(\\''+p+'\\',\\''+sl+'\\')\">➕ Adaugă concediu</button></div></div>';\r\n  return h;\r\n}\r\n\r\n/* ===== EDITOR DE RUTINĂ (sarcini recurente proprii + ascunderea celor standard) ===== */\r\nfunction editRutina(p){EDITRUTINA=EDITRUTINA===p?'':p;render();}\r\nfunction adaugaRutina(p,sl){\r\n  const t=((document.getElementById('rt_text_'+sl)||{}).value||'').trim();\r\n  if(!t){alert('Scrie sarcina recurentă.');return;}\r\n  const dur=+((document.getElementById('rt_dur_'+sl)||{}).value)||20;\r\n  const bloc=(document.getElementById('rt_bloc_'+sl)||{}).value||'d';\r\n  const prio=(document.getElementById('rt_prio_'+sl)||{}).value||'';\r\n  const zile=[].slice.call(document.querySelectorAll('.rt_zi_'+sl)).filter(c=>c.checked).map(c=>+c.value);\r\n  if(!zile.length){alert('Alege cel puțin o zi.');return;}\r\n  RUTINA_CUSTOM.push({id:uid(),pers:p,t:t,dur:dur,bloc:bloc,prio:prio,zile:zile,mod_la:acum()});\r\n  saveRutinaCustom();render();toast('Adăugat în rutină ✓');\r\n}\r\nfunction stergeRutina(id){const r=RUTINA_CUSTOM.find(x=>x.id===id);if(r){r.sters=true;r.mod_la=acum();}saveRutinaCustom();render();toast('Șters din rutină');}\r\nfunction resetRovr(pk){delete ROVR[pk];marcheazaSters('rovr-'+pk);saveRovr();render();toast('Readusă la normal ✓');}\r\nfunction toggleRutinaStd(p,ts){const k=slug(p)+'|'+ts;if(RUTINA_OFF[k]){delete RUTINA_OFF[k];marcheazaSters('roff-'+k);}else{RUTINA_OFF[k]={at:todayIso()};revine('roff-'+k);}saveRutinaOff();render();}\r\nfunction randRutinaEditor(p){\r\n  const sl=slug(p), zn={1:'Lu',2:'Ma',3:'Mi',4:'Jo',5:'Vi'};\r\n  const mele=RUTINA_CUSTOM.filter(r=>!r.sters&&r.pers===p);\r\n  let h='<div class=\"card\" style=\"border-color:var(--blue)\"><div class=\"chead\"><b>🔁 Rutina — '+esc(p)+'</b><span class=\"right\"><button class=\"btn small\" onclick=\"editRutina(\\''+p+'\\')\">Închide</button></span></div>';\r\n  h+='<div class=\"mini\" style=\"font-weight:600;margin-top:4px\">Sarcinile tale recurente adăugate:</div>';\r\n  if(mele.length)h+=mele.map(r=>'<div class=\"slot\"><div class=\"bd\">'+(r.prio==='urg'?'🔥 ':r.prio==='imp'?'⭐ ':'')+esc(r.t)+' <span class=\"mini\">· '+(+r.dur||20)+' min · '+(r.bloc==='p'?'după-amiaza':'dimineața')+' · '+(r.zile||[]).map(z=>zn[z]).join(' ')+'</span></div><button class=\"btn small\" onclick=\"stergeRutina(\\''+r.id+'\\')\" title=\"Șterge\">✕</button></div>').join('');\r\n  else h+='<div class=\"mini\" style=\"padding:4px 2px\">Niciuna încă — adaugă mai jos.</div>';\r\n  h+='<div class=\"frow\" style=\"border:none;margin-top:6px\"><input type=\"text\" id=\"rt_text_'+sl+'\" placeholder=\"Sarcină recurentă nouă\" style=\"flex:1;min-width:190px\">'\r\n   +'<label>Durata</label><select id=\"rt_dur_'+sl+'\">'+[10,15,20,30,45,60].map(d=>'<option value=\"'+d+'\"'+(d===20?' selected':'')+'>'+d+' min</option>').join('')+'</select>'\r\n   +'<select id=\"rt_bloc_'+sl+'\"><option value=\"d\">dimineața</option><option value=\"p\">după-amiaza</option></select>'\r\n   +'<select id=\"rt_prio_'+sl+'\"><option value=\"\">normală</option><option value=\"imp\">⭐ importantă</option><option value=\"urg\">🔥 urgentă</option></select></div>';\r\n  h+='<div class=\"frow\" style=\"border:none\"><label>Zile:</label>'\r\n   +[1,2,3,4,5].map(z=>'<label style=\"font-weight:400;margin-right:6px\"><input type=\"checkbox\" class=\"rt_zi_'+sl+'\" value=\"'+z+'\" checked> '+zn[z]+'</label>').join('')\r\n   +'<button class=\"btn primary small\" onclick=\"adaugaRutina(\\''+p+'\\',\\''+sl+'\\')\">➕ Adaugă în rutină</button></div>';\r\n  const baza=rutinaBaza(ZI).filter(t=>t.pers===p), seen={};\r\n  const std=baza.filter(t=>{const k=slug(p)+'|'+slug(t.t);if(seen[k])return false;seen[k]=1;return true;});\r\n  if(std.length){\r\n    h+='<div class=\"mini\" style=\"font-weight:600;margin-top:8px\">Sarcini standard (din șablon) — ascunde ce nu se aplică ție:</div>';\r\n    std.forEach(t=>{const ts=slug(t.t),k=slug(p)+'|'+ts,hidden=!!RUTINA_OFF[k];\r\n      h+='<div class=\"slot\" style=\"'+(hidden?'opacity:.5':'')+'\"><div class=\"bd\">'+esc(t.t)+(hidden?' <span class=\"mini\">(ascunsă)</span>':'')+'</div><button class=\"btn small\" onclick=\"toggleRutinaStd(\\''+p+'\\',\\''+ts+'\\')\">'+(hidden?'↩ Arată':'Ascunde')+'</button></div>';});\r\n  }\r\n  /* sarcini tăiate/modificate permanent de pe rând (✏️/✕) — readu la normal */\r\n  const rov=Object.keys(ROVR).map(k=>ROVR[k]?Object.assign({_k:k},ROVR[k]):null).filter(x=>x&&x.pers===p&&(x.sters||x.t!=null));\r\n  if(rov.length){\r\n    h+='<div class=\"mini\" style=\"font-weight:600;margin-top:8px\">Sarcini tăiate/modificate de tine (permanent) — readu la normal:</div>';\r\n    rov.forEach(r=>{h+='<div class=\"slot\"><div class=\"bd\">'+esc(r.orig||r.t||r._k)+' <span class=\"mini\">· '+(r.sters?'tăiată':'→ „'+esc(r.t||'')+'\", '+(+r.dur||0)+' min')+'</span></div><button class=\"btn small\" onclick=\"resetRovr(\\''+r._k+'\\')\">↩ Readu</button></div>';});\r\n  }\r\n  h+='</div>';\r\n  return h;\r\n}\r\n\r\n/* Prioritatea unei sarcini ad-hoc: '' normală · 'imp' importantă · 'urg' urgentă.\r\n   Compat cu vechiul câmp boolean „urgent\". */\r\nfunction prioExtra(e){return (e&&e.prio)||(e&&e.urgent?'urg':'');}\r\n/* Câmpurile unei sarcini ad-hoc — reutilizate la „dă o sarcină\" și la editare. */\r\nfunction campuriExtra(pfx,v){\r\n  v=v||{};\r\n  const durs=[15,30,45,60,120], durL={15:'15 min',30:'30 min',45:'45 min',60:'1 oră',120:'2 ore'};\r\n  return '<div class=\"frow\">'\r\n   +'<label>Cine</label><select id=\"'+pfx+'pers\">'+TOTI.map(p=>'<option'+(p===v.pers?' selected':'')+'>'+p+'</option>').join('')+'</select>'\r\n   +'<label>Când</label><input type=\"date\" id=\"'+pfx+'data\" value=\"'+esc(v.data||todayIso())+'\">'\r\n   +'<label>Durata</label><select id=\"'+pfx+'dur\">'+durs.map(d=>'<option value=\"'+d+'\"'+((+v.dur||30)===d?' selected':'')+'>'+durL[d]+'</option>').join('')+'</select>'\r\n   +'<label>Când în zi</label><select id=\"'+pfx+'bloc\"><option value=\"d\"'+(v.bloc!=='p'?' selected':'')+'>dimineața</option><option value=\"p\"'+(v.bloc==='p'?' selected':'')+'>după-amiaza</option></select></div>'\r\n   +'<div class=\"frow\"><input type=\"text\" id=\"'+pfx+'text\" placeholder=\"Ce are de făcut\" value=\"'+esc(v.t||'')+'\" style=\"flex:1;min-width:220px\">'\r\n   +'<label>Prioritate</label><select id=\"'+pfx+'prio\">'\r\n   +'<option value=\"\"'+(prioExtra(v)===''?' selected':'')+'>normală</option>'\r\n   +'<option value=\"imp\"'+(prioExtra(v)==='imp'?' selected':'')+'>⭐ importantă</option>'\r\n   +'<option value=\"urg\"'+(prioExtra(v)==='urg'?' selected':'')+'>🔥 urgentă</option></select></div>';\r\n}\r\nfunction citesteCampuriExtra(pfx){\r\n  return {t:(document.getElementById(pfx+'text').value||'').trim(),\r\n    pers:document.getElementById(pfx+'pers').value,\r\n    data:document.getElementById(pfx+'data').value||todayIso(),\r\n    dur:+document.getElementById(pfx+'dur').value,\r\n    bloc:document.getElementById(pfx+'bloc').value,\r\n    prio:(document.getElementById(pfx+'prio')||{}).value||'',\r\n    urgent:((document.getElementById(pfx+'prio')||{}).value||'')==='urg'};\r\n}\r\nfunction randUnExtra(e){\r\n  const b=BIFE['extra|'+e.id];\r\n  let h='<div class=\"slot '+(b?'done':'')+'\"><div class=\"hh\">'+e.data.slice(8)+'.'+e.data.slice(5,7)+'</div>'\r\n    +(e.pers===USER?'<input type=\"checkbox\" '+(b?'checked':'')+' onchange=\"tick(\\'extra|'+e.id+'\\',this.checked,this)\">':'')\r\n    +'<div class=\"bd\"><span class=\"tag trsp\">'+esc(e.pers)+'</span>'+((!b&&e.data<todayIso())?'<span class=\"tag\" style=\"background:var(--amber-soft);color:var(--amber)\">⏰ restantă</span> ':'')+(prioExtra(e)==='urg'?'<b style=\"color:var(--red-deep)\">🔥 URGENT · </b>':prioExtra(e)==='imp'?'<b style=\"color:var(--amber)\">⭐ Important · </b>':'')+esc(e.t)\r\n    +' <span class=\"mini\">· '+e.dur+' min · de la '+esc(e.by||'?')+(e.serie?' · 🔁':'')+'</span>'\r\n    +(b?'<span class=\"byline\">✓ făcut de '+esc(b.by)+' · '+b.at+'</span>':'<span class=\"byline\">încă nebifată</span>')+'</div>'\r\n    +'<button class=\"btn small\" onclick=\"editExtra(\\''+e.id+'\\')\" title=\"Modifică sau reatribuie\">✏️</button>'\r\n    +'<button class=\"btn small\" onclick=\"stergeExtra(\\''+e.id+'\\')\" title=\"Șterge\">✕</button></div>';\r\n  if(EDITEXTRA===e.id){\r\n    h+='<div class=\"card\" style=\"border-color:var(--blue)\"><div class=\"chead\"><b>✏️ Modifică sarcina</b></div>'\r\n      +campuriExtra('ed_',e)\r\n      +'<div class=\"frow\"><button class=\"btn primary\" onclick=\"salveazaExtra(\\''+e.id+'\\')\">Salvează</button>'\r\n      +'<button class=\"btn small\" onclick=\"EDITEXTRA=\\'\\';render()\">Renunț</button>'\r\n      +(e.serie?'<span style=\"flex:1\"></span><button class=\"btn small\" onclick=\"stergeSerieExtra(\\''+e.serie+'\\')\" title=\"Șterge toate sarcinile din această serie\">🗑 Șterge seria</button>':'')\r\n      +'</div></div>';\r\n  }\r\n  return h;\r\n}\r\nfunction randListaExtra(titlu,lista){\r\n  if(!lista.length)return '';\r\n  let h='<div class=\"card\"><div class=\"chead\"><b>'+titlu+'</b><span class=\"right mini\">'+lista.length+'</span></div>';\r\n  lista.forEach(e=>{h+=randUnExtra(e);});\r\n  return h+'</div>';\r\n}\r\nfunction randExtra(){\r\n  const potiNotifica='Notification' in window;\r\n  let h='<div class=\"info\">Oricine poate da o sarcină oricui — Andreea către Paula, Paula către Ștefania, oricare către Vlad, Gabriel sau Andrei. Sarcina apare în ziua aleasă direct în agenda persoanei, marcată cu 📌, iar colegul e anunțat chiar aici, în program: banner mov + sunet'\r\n   +(potiNotifica?' + notificare de browser dacă are pagina deschisă':'')\r\n   +'. Totul ajunge la el în cel mult 10–15 secunde.</div>';\r\n  if(potiNotifica&&Notification.permission==='default')\r\n    h+='<div class=\"warn\">🔔 Ca să primești notificări pe acest calculator când ți se dă o sarcină, pornește-le o singură dată: '\r\n     +'<button class=\"btn small\" onclick=\"cereNotificari()\">Pornește notificările</button></div>';\r\n  h+='<div class=\"card\"><div class=\"chead\"><b>Dă o sarcină</b>'+(USER?'<span class=\"sub\">trimisă de '+esc(USER)+'</span>':'<span class=\"sub\" style=\"color:var(--red-deep)\">alege-ți numele din dreapta sus</span>')+'</div>'\r\n   +campuriExtra('e_',{})\r\n   +'<div class=\"frow\"><label>Repetă</label><select id=\"e_rep\"><option value=\"\">o singură dată</option><option value=\"zi\">în fiecare zi</option><option value=\"sapt\">în fiecare săptămână</option></select>'\r\n   +'<label>Până la</label><input type=\"date\" id=\"e_pana\" value=\"\">'\r\n   +'<button class=\"btn primary\" onclick=\"adaugaExtra()\">Trimite sarcina</button></div></div>';\r\n  const active=EXTRA.filter(e=>!e.sters);\r\n  if(!active.length)return h+'<div class=\"empty\">Nicio sarcină dată deocamdată.</div>';\r\n  const cmp=(a,b)=>a.data<b.data?1:-1;\r\n  if(USER){\r\n    h+=randListaExtra('📥 Primite de mine',active.filter(e=>e.pers===USER).sort(cmp));\r\n    h+=randListaExtra('📤 Trimise de mine',active.filter(e=>e.by===USER&&e.pers!==USER).sort(cmp));\r\n    h+=randListaExtra('👥 Restul echipei',active.filter(e=>e.pers!==USER&&e.by!==USER).sort(cmp));\r\n  }else{\r\n    h+=randListaExtra('Sarcini trimise',active.sort(cmp));\r\n  }\r\n  return h;\r\n}\r\nfunction adaugaExtra(){\r\n  const d=citesteCampuriExtra('e_');\r\n  if(!d.t){alert('Scrie ce are de făcut.');return;}\r\n  const rep=(document.getElementById('e_rep')||{}).value||'';\r\n  const pana=(document.getElementById('e_pana')||{}).value||'';\r\n  const date=[d.data];\r\n  if(rep&&pana&&pana>=d.data){\r\n    const step=rep==='sapt'?7:1; let cur=addDays(d.data,step), n=1;\r\n    while(cur<=pana&&n<60){date.push(cur);cur=addDays(cur,step);n++;}\r\n  }\r\n  const serie=date.length>1?uid():'';\r\n  date.forEach(dt=>{EXTRA.push({id:uid(),pers:d.pers,data:dt,t:d.t,dur:d.dur,bloc:d.bloc,prio:d.prio,urgent:d.urgent,by:USER||'?',serie:serie,cand:todayIso(),mod_la:acum()});});\r\n  saveExtra();EDITEXTRA='';render();\r\n  toast(date.length>1?('Serie de '+date.length+' sarcini trimisă ✓ — '+d.pers):('Sarcină trimisă ✓ — '+d.pers+' o primește în câteva secunde'));\r\n}\r\nfunction editExtra(id){EDITEXTRA=EDITEXTRA===id?'':id;render();}\r\nfunction salveazaExtra(id){\r\n  const e=EXTRA.find(x=>x.id===id);if(!e)return;\r\n  const d=citesteCampuriExtra('ed_');\r\n  if(!d.t){alert('Scrie ce are de făcut.');return;}\r\n  e.pers=d.pers;e.data=d.data;e.t=d.t;e.dur=d.dur;e.bloc=d.bloc;e.prio=d.prio;e.urgent=d.urgent;e.mod_la=acum();\r\n  saveExtra();EDITEXTRA='';render();toast('Sarcină modificată ✓');\r\n}\r\nfunction stergeExtra(id){if(!confirm('Ștergi sarcina?'))return;const e=EXTRA.find(x=>x.id===id);if(e){e.sters=true;e.mod_la=acum();}saveExtra();EDITEXTRA='';render();}\r\nfunction stergeSerieExtra(serie){if(!serie||!confirm('Ștergi toate sarcinile din această serie?'))return;let n=0;EXTRA.forEach(e=>{if(e.serie===serie&&!e.sters){e.sters=true;e.mod_la=acum();n++;}});saveExtra();EDITEXTRA='';render();toast('Serie ștearsă ('+n+') ✓');}\r\n\r\n/* ===== EDITAREA ORICĂREI SARCINI DIN ZI (generate sau ad-hoc) ===== */\r\n/* Sarcinile ad-hoc se editează în formularul lor din „Sarcini\". Cele generate\r\n   de motor se anulează/înlocuiesc printr-un strat de suprascriere pe ziua aceea. */\r\nfunction editSlot(key){\r\n  if(String(key).indexOf('extra|')===0){setView('extra');EDITEXTRA=String(key).slice(6);render();toast('Editează sarcina în „Sarcini\"');return;}\r\n  EDITSLOT=EDITSLOT===key?'':key;render();\r\n}\r\n/* pentru o cheie de rutină: cheia permanentă (pers|titlu) + persoana + titlul ORIGINAL */\r\nfunction pkInfo(key){\r\n  const pk=rovrKey(key); let pers='', orig='';\r\n  const m=rutina(ZI).find(x=>(slug(x.pers)+'|'+(x.cazId&&x.cazId!=='gen'?x.cazId+'|':'')+slug(x.t).slice(0,44))===pk);\r\n  if(m){pers=m.pers;orig=m.t;}\r\n  return {pk:pk,pers:pers,orig:orig};\r\n}\r\nfunction anuleazaSlot(key){\r\n  if(String(key).indexOf('extra|')===0){\r\n    if(!confirm('Anulezi această sarcină din ziua de azi?'))return;\r\n    const e=EXTRA.find(x=>x.id===String(key).slice(6));if(e){e.sters=true;e.mod_la=acum();}saveExtra();\r\n    EDITSLOT='';render();toast('Sarcină anulată');return;\r\n  }\r\n  if(isRutKey(key)){\r\n    if(!confirm('Scoți această sarcină din rutină? Nu va mai apărea în zilele următoare. O poți readuce oricând din „🔁 Rutină\".'))return;\r\n    const i=pkInfo(key);\r\n    ROVR[i.pk]=Object.assign({pers:i.pers,orig:i.orig},ROVR[i.pk],{sters:true});\r\n    revine('rovr-'+i.pk);saveRovr();\r\n    EDITSLOT='';render();toast('Scoasă din rutină ✓ (permanent)');return;\r\n  }\r\n  if(!confirm('Anulezi această sarcină din ziua de azi?'))return;\r\n  OVERRIDES[key]=Object.assign({},OVERRIDES[key],{sters:true});revine('ovr-'+key);saveOverrides();\r\n  EDITSLOT='';render();toast('Sarcină anulată');\r\n}\r\nfunction salveazaSlot(key){\r\n  const t=(document.getElementById('sl_text').value||'').trim();\r\n  if(!t){alert('Scrie ce e de făcut.');return;}\r\n  const dur=+(document.getElementById('sl_dur')||{}).value||30;\r\n  if(isRutKey(key)){\r\n    const i=pkInfo(key);\r\n    ROVR[i.pk]=Object.assign({pers:i.pers,orig:i.orig},ROVR[i.pk],{t:t,dur:dur,sters:false});\r\n    revine('rovr-'+i.pk);saveRovr();\r\n    EDITSLOT='';render();toast('Rutină modificată ✓ (rămâne pentru toate zilele)');return;\r\n  }\r\n  OVERRIDES[key]=Object.assign({},OVERRIDES[key],{t:t,dur:dur,sters:false});\r\n  revine('ovr-'+key);\r\n  saveOverrides();EDITSLOT='';render();toast('Sarcină modificată ✓');\r\n}\r\nfunction slotEditor(t){\r\n  const perm=isRutKey(t.key);\r\n  return '<div class=\"card\" style=\"border-color:var(--blue)\"><div class=\"chead\"><b>✏️ Modifică / înlocuiește sarcina</b>'\r\n   +'<span class=\"sub\">'+(perm?'modificarea rămâne în rutină, pentru toate zilele':'textul înlocuiește sarcina generată doar pentru ziua asta')+'</span></div>'\r\n   +'<div class=\"frow\"><input type=\"text\" id=\"sl_text\" value=\"'+esc(t.t)+'\" placeholder=\"Ce e de făcut\" style=\"flex:1;min-width:240px\">'\r\n   +'<label>Durata</label><select id=\"sl_dur\">'+[10,15,20,30,45,60,90,120].map(d=>'<option value=\"'+d+'\"'+((+t.dur||30)===d?' selected':'')+'>'+d+' min</option>').join('')+'</select>'\r\n   +'<button class=\"btn primary\" onclick=\"salveazaSlot(\\''+t.key+'\\')\">Salvează</button>'\r\n   +'<button class=\"btn small\" onclick=\"EDITSLOT=\\'\\';render()\">Renunț</button></div></div>';\r\n}\r\n\r\n/* ===== PLANIFICAREA ZILEI DE MÂINE (blocul de la finalul programului) ===== */\r\n/* Fiecare, în ultimul sfert de oră, alege/scrie sarcinile urgente apoi importante\r\n   pentru ziua lucrătoare următoare, la prima oră. Vineri → luni (sare weekendul). */\r\nfunction randPlanMaine(t,p){\r\n  const maine=t.maine||ziuaLucrUrm(ZI), b=BIFE[t.key], mine=(p===USER), sl=slug(p), rk={urg:0,imp:1};\r\n  const q=EXTRA.filter(e=>!e.sters&&e.pers===p&&e.data===maine&&(prioExtra(e)==='urg'||prioExtra(e)==='imp'))\r\n    .sort((a,b)=>rk[prioExtra(a)]-rk[prioExtra(b)]);\r\n  let h='<div class=\"slot '+(b?'done':'')+'\" style=\"border-left:4px solid var(--red-deep);background:var(--red-soft)\"><div class=\"hh\">'+hhmm(t.de)+'–'+hhmm(t.la)+'</div>'\r\n   +'<input type=\"checkbox\" '+(b?'checked':'')+' onchange=\"tick(\\''+t.key+'\\',this.checked,this)\" title=\"Am planificat ziua de mâine\">'\r\n   +'<div class=\"bd\"><b>⚡ Planifică mâine — '+fmtZi(maine)+'</b> <span class=\"mini\">ce faci la prima oră: întâi urgent, apoi important</span>';\r\n  if(q.length)h+=q.map(e=>'<div style=\"margin-top:4px\">'+(prioExtra(e)==='urg'?'🔥':'⭐')+' '+esc(e.t)+(mine?' <a href=\"#\" onclick=\"stergePlanMaine(\\''+e.id+'\\');return false\" style=\"color:var(--red-deep);text-decoration:none\" title=\"Scoate\">✕</a>':'')+'</div>').join('');\r\n  else h+='<div class=\"mini\" style=\"margin-top:4px\">Nimic pregătit pentru mâine încă.</div>';\r\n  if(mine){\r\n    const rank=e=>{const x=prioExtra(e);return x==='urg'?0:x==='imp'?1:2;};\r\n    const azi=EXTRA.filter(e=>!e.sters&&e.pers===p&&e.data===ZI&&!BIFE['extra|'+e.id]).sort((a,b)=>rank(a)-rank(b));\r\n    if(azi.length){\r\n      h+='<div class=\"mini\" style=\"margin-top:8px;font-weight:600\">De azi, neterminate — mută pe mâine:</div>';\r\n      h+=azi.map(e=>'<div style=\"margin-top:2px\">'+(prioExtra(e)==='urg'?'🔥 ':prioExtra(e)==='imp'?'⭐ ':'• ')+esc(e.t)+' <a href=\"#\" onclick=\"mutaPeMaine(\\''+e.id+'\\',\\''+maine+'\\');return false\" style=\"color:var(--blue);text-decoration:none;font-weight:600\" title=\"Mută pe mâine dimineață\">→ mâine</a></div>').join('');\r\n    }\r\n  }\r\n  if(mine)h+='<div class=\"frow\" style=\"margin-top:6px;border:none;padding:0\">'\r\n   +'<input type=\"text\" id=\"pm_'+sl+'\" placeholder=\"Ce faci mâine la prima oră\" style=\"flex:1;min-width:200px\">'\r\n   +'<select id=\"pmpr_'+sl+'\"><option value=\"urg\">🔥 urgentă</option><option value=\"imp\">⭐ importantă</option></select>'\r\n   +'<button class=\"btn small\" onclick=\"adaugaPlanMaine(\\''+sl+'\\',\\''+p+'\\',\\''+maine+'\\')\">➕ Pentru mâine</button></div>';\r\n  h+='</div></div>';\r\n  return h;\r\n}\r\nfunction adaugaPlanMaine(sl,pers,maine){\r\n  const inp=document.getElementById('pm_'+sl), sel=document.getElementById('pmpr_'+sl);\r\n  const t=((inp&&inp.value)||'').trim(); if(!t){alert('Scrie ce faci mâine la prima oră.');return;}\r\n  const prio=((sel&&sel.value)||'urg');\r\n  EXTRA.push({id:uid(),pers:pers,data:maine,t:t,dur:30,bloc:'d',prio:prio,urgent:prio==='urg',by:USER||pers,cand:todayIso(),mod_la:acum()});\r\n  saveExtra();render();toast('Pregătit pentru mâine ✓');\r\n}\r\nfunction stergePlanMaine(id){const e=EXTRA.find(x=>x.id===id);if(e){e.sters=true;e.mod_la=acum();}saveExtra();render();toast('Șters');}\r\nfunction mutaPeMaine(id,maine){const e=EXTRA.find(x=>x.id===id);if(e){e.data=maine;e.mod_la=acum();}saveExtra();render();toast('Mutat pe mâine ✓');}\r\n/* Amână orice sarcină din zi pe ziua lucrătoare următoare. Ad-hoc: re-datează.\r\n   Generată: anulează instanța de azi (override) + creează o copie ad-hoc pe mâine dimineață. */\r\nfunction amanaSlot(key){\r\n  const maine=ziuaLucrUrm(ZI);\r\n  if(String(key).indexOf('extra|')===0){const e=EXTRA.find(x=>x.id===String(key).slice(6));if(e){e.data=maine;e.mod_la=acum();}saveExtra();render();toast('Amânat pe '+fmtZi(maine)+' ✓');return;}\r\n  const t=sarciniZiBrut(ZI).find(x=>x.key===key);\r\n  if(!t){toast('Nu s-a putut amâna');return;}\r\n  OVERRIDES[key]=Object.assign({},OVERRIDES[key],{sters:true});revine('ovr-'+key);\r\n  EXTRA.push({id:uid(),pers:t.pers,data:maine,t:t.t,dur:t.dur||30,bloc:'d',prio:t.prio||'',urgent:t.prio==='urg',by:USER||t.pers,cand:todayIso(),mod_la:acum(),amanata:true});\r\n  saveOverrides();saveExtra();render();toast('Amânat pe '+fmtZi(maine)+' ✓');\r\n}\r\n\r\nfunction randRestante(){\r\n  const r=restante();\r\n  if(!r.length)return '<div class=\"empty\">Nicio restanță. Totul bifat la zi. 👏</div>';\r\n  const urg=t=>t.zile===7||/⚠️|🔥|urgen/i.test(t.t);\r\n  const grup={};r.forEach(t=>{(grup[t.pers]=grup[t.pers]||[]).push(t);});\r\n  let h='<div class=\"info\">Aici apar doar restanțele din ziua lucrătoare anterioară — cele mai vechi de 48 de ore se șterg singure. Bifezi ce ai recuperat; cu ✕ elimini o sarcină care nu mai are rost.</div>';\r\n  Object.keys(grup).forEach(p=>{\r\n    const bl=grup[p].length>PRAG_RESTANTE;\r\n    grup[p].sort((a,b)=>(urg(b)?1:0)-(urg(a)?1:0)||(a.iso<b.iso?-1:1));\r\n    h+='<div class=\"card\"><div class=\"chead\"><b>'+esc(p)+'</b>'+(bl?'<span class=\"tag t7\">blocat · mai sunt '+(grup[p].length-PRAG_RESTANTE)+' de recuperat</span>':'')+'<span class=\"right mini\">'+grup[p].length+' restanțe</span></div>';\r\n    grup[p].forEach(t=>h+='<div class=\"slot'+(urg(t)?' over':'')+'\"><div class=\"hh\">'+t.iso.slice(8)+'.'+t.iso.slice(5,7)+'</div>'\r\n      +'<input type=\"checkbox\" onchange=\"tick(\\''+t.key+'\\',this.checked,this)\">'\r\n      +'<div class=\"bd\">'+(urg(t)?'<span class=\"tag t7\">🔥 URGENT</span>':'')+'<span class=\"tag '+TIERS[t.zile].cls+'\">'+esc(t.caz)+'</span>'+esc(t.t)+'</div>'\r\n      +'<button class=\"btn small\" onclick=\"elimRest(\\''+t.key+'\\')\" title=\"Elimină restanța — nu se mai numără nici la realizate, nici la restanțe\">✕</button></div>');\r\n    h+='</div>';\r\n  });\r\n  return h;\r\n}\r\nfunction elimRest(key){\r\n  if(!USER){alert('Alege-ți numele din dreapta sus.');return;}\r\n  BIFE[key]={by:USER,at:new Date().toLocaleString('ro-RO',{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'}),eliminat:true,ts:acum()};\r\n  revine('bifa-'+key);\r\n  saveBife();render();toast('Restanță eliminată ✕');\r\n}\r\n\r\nfunction randFise(){\r\n  const azi=dow(todayIso())>=1&&dow(todayIso())<=5?todayIso():addDays(todayIso(),8-dow(todayIso())||1);\r\n  let h='<div class=\"info\">Fișa se generează din motorul programului: tot ce apare aici ajunge automat în „Ziua mea\", cu oră și bifă.</div>';\r\n  ECHIPA.forEach(p=>{\r\n    const zileSapt=[1,2,3,4,5].map(w=>{let d=todayIso();for(let i=0;i<7;i++){if(dow(addDays(d,i))===w)return addDays(d,i);}return d;});\r\n    const set=new Map();\r\n    zileSapt.forEach(iso=>rutina(iso).filter(t=>t.pers===p).forEach(t=>{\r\n      const k=t.t.replace(/\\s*\\([^)]*\\)\\s*$/,'');\r\n      set.set(k,(set.get(k)||new Set()).add(ZILE[dow(iso)]));\r\n    }));\r\n    h+='<div class=\"card\"><div class=\"chead\"><b>'+p+'</b><span class=\"sub\">'+ROL[p]+'</span>'\r\n      +'<span class=\"right\"><button class=\"btn small\" onclick=\"fisaWord(\\''+p+'\\')\">📄 Word</button></span></div>';\r\n    [...set.entries()].forEach(([t,zile])=>{\r\n      const et=zile.size===5?'zilnic':[...zile].join(', ');\r\n      h+='<div class=\"slot\"><div class=\"hh\">'+et+'</div><div class=\"bd\">'+esc(t)+'</div></div>';\r\n    });\r\n    h+='<div class=\"freqhead\">Pe caz</div>';\r\n    const pc=planCaz({id:'x',nume:'—',zile:15,start:todayIso(),resp:p,gata:false});\r\n    const uniq=new Set();\r\n    Object.keys(pc).forEach(k=>pc[k].filter(t=>t.pers===p).forEach(t=>uniq.add(t.t)));\r\n    if(!uniq.size)h+='<div class=\"slot\"><div class=\"hh\">·</div><div class=\"bd mini\">Nicio sarcină specifică pe caz.</div></div>';\r\n    [...uniq].forEach(t=>h+='<div class=\"slot\"><div class=\"hh\">·</div><div class=\"bd\">'+esc(t)+'</div></div>');\r\n    h+='</div>';\r\n  });\r\n  return h;\r\n}\r\nfunction fisaWord(p){\r\n  let items=[];\r\n  document.querySelectorAll('.card').forEach(c=>{const b=c.querySelector('.chead b');if(b&&b.textContent===p)c.querySelectorAll('.slot').forEach(s=>items.push(s.querySelector('.hh').textContent+' — '+s.querySelector('.bd').textContent));});\r\n  const H='<html><head><meta charset=\"utf-8\"></head><body style=\"font-family:Georgia,serif\"><h1>Fișa postului — '+p+'</h1><h3>'+(ROL[p]||'')+'</h3><p>Program: 8:30–15:30 · 8:30–9:00 citit cărți · 12:00–12:30 pauză de masă</p><ul>'+items.map(i=>'<li>'+i+'</li>').join('')+'</ul><p style=\"color:#888;font-size:11px\">Asociația „salvează o inimă\" · generat '+new Date().toLocaleDateString('ro-RO')+'</p></body></html>';\r\n  const a=document.createElement('a');a.href=URL.createObjectURL(new Blob(['\\ufeff'+H],{type:'application/msword'}));\r\n  a.download='fisa-postului-'+slug(p)+'.doc';a.click();\r\n}\r\nfunction salveazaProiect(){\r\n  const data={aplicatie:'program-lucru-cazuri',versiune:3,salvatLa:new Date().toISOString(),salvatDe:USER||'',cazuri:CAZURI,bife:BIFE,praguri:PRAGURI,extra:EXTRA};\r\n  const a=document.createElement('a');\r\n  a.href=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));\r\n  a.download='proiect-cazuri-'+todayIso()+'.json';a.click();\r\n  toast('Proiect salvat ✓');\r\n}\r\nfunction incarcaProiect(input){\r\n  const f=input.files&&input.files[0]; if(!f)return;\r\n  const r=new FileReader();\r\n  r.onload=()=>{\r\n    try{\r\n      const d=JSON.parse(r.result);\r\n      if(!d||!d.cazuri)throw 0;\r\n      const cand=(d.salvatLa||'').slice(0,10), cine=d.salvatDe?' de '+d.salvatDe:'';\r\n      if(!confirm('Încarci copia din '+cand+cine+'?\\n\\n'+d.cazuri.length+' cazuri, '+Object.keys(d.bife||{}).length+' bife.\\n\\nAceasta ÎNLOCUIEȘTE tot ce e acum în instrument, pentru toată echipa.'))return;\r\n      CAZURI=d.cazuri||[];BIFE=d.bife||{};PRAGURI=d.praguri||{};\r\n      if(Array.isArray(d.extra))EXTRA=d.extra;\r\n      saveCaz();saveBife();savePrag();saveExtra();render();toast('Proiect încărcat ✓');\r\n    }catch(e){alert('Fișierul nu e o copie validă a proiectului.');}\r\n    input.value='';\r\n  };\r\n  r.readAsText(f);\r\n}\r\nfunction construiesteRaport(zile){\r\n  const pana=todayIso(), de=addDays(pana,-(zile-1));\r\n  const perPers={};\r\n  ECHIPA.forEach(p=>perPers[p]={gata:0,tot:0,minGata:0,minTot:0,taiat:0,lista:[]});\r\n  for(let i=0;i<zile;i++){\r\n    const iso=addDays(de,i);\r\n    sarciniZi(iso).filter(t=>t.pers!=='Familia').forEach(t=>{\r\n      if(!perPers[t.pers])perPers[t.pers]={gata:0,tot:0,minGata:0,minTot:0,taiat:0,lista:[]};\r\n      const min=+t.dur||0;\r\n      perPers[t.pers].tot++;perPers[t.pers].minTot+=min;\r\n      const b=BIFE[t.key];\r\n      if(b&&!b.eliminat){perPers[t.pers].gata++;perPers[t.pers].minGata+=min;perPers[t.pers].lista.push({iso,t:t.t,caz:t.caz,dur:min});}\r\n    });\r\n    /* munca generată care n-a încăput în ziua de 5h = presiune peste program */\r\n    alegePentruZi(iso).taiate.forEach(t=>{if(perPers[t.pers])perPers[t.pers].taiat+=(+t.dur||0);});\r\n  }\r\n  const fam={gata:0,tot:0};\r\n  for(let i=0;i<zile;i++)sarciniZi(addDays(de,i)).filter(t=>t.pers==='Familia').forEach(t=>{fam.tot++;if(BIFE[t.key])fam.gata++;});\r\n  const pct=(a,b)=>b?Math.round(a/b*100):0, ore=m=>(Math.round(m/60*10)/10)+'h';\r\n  let H='<html><head><meta charset=\"utf-8\"></head><body style=\"font-family:Calibri,Arial,sans-serif\">'\r\n   +'<h1 style=\"font-family:Georgia,serif;color:#9E1F27\">Raport de activitate &middot; Asocia&#539;ia „salveaz&#259; o inim&#259;\"</h1>'\r\n   +'<p><b>Perioada:</b> '+de+' – '+pana+' ('+zile+(zile===1?' zi':' zile')+')<br><b>Generat:</b> '+new Date().toLocaleString('ro-RO')+(USER?' de '+USER:'')+'</p>'\r\n   +'<h2>Sinteză</h2>'\r\n   +'<p style=\"font-size:12px;color:#555\">Procentul e pe <b>efort (minute)</b>, nu pe număr de sarcini. „Peste program\" = munca generată care n-a încăput în ziua de 5h și a devenit restanță — cu cât e mai mare, cu atât persoana e mai suprasolicitată.</p>'\r\n   +'<table border=\"1\" cellpadding=\"6\" cellspacing=\"0\" style=\"border-collapse:collapse;font-size:12px\">'\r\n   +'<tr style=\"background:#F7E5E4\"><th>Persoană</th><th>Realizate</th><th>Din total</th><th>Ore realizate</th><th>Ore planificate</th><th>Peste program</th><th>Procent efort</th></tr>';\r\n  ECHIPA.forEach(p=>{const d=perPers[p];H+='<tr><td>'+p+'</td><td>'+d.gata+'</td><td>'+d.tot+'</td><td>'+ore(d.minGata)+'</td><td>'+ore(d.minTot)+'</td><td>'+(d.taiat?'<b style=\"color:#9E1F27\">'+ore(d.taiat)+'</b>':'—')+'</td><td>'+pct(d.minGata,d.minTot)+'%</td></tr>';});\r\n  H+='<tr style=\"background:#E4EEF2\"><td>Familiile</td><td>'+fam.gata+'</td><td>'+fam.tot+'</td><td>—</td><td>—</td><td>—</td><td>'+pct(fam.gata,fam.tot)+'%</td></tr></table>';\r\n  H+='<h2>Cazuri</h2><table border=\"1\" cellpadding=\"6\" cellspacing=\"0\" style=\"border-collapse:collapse;font-size:12px\">'\r\n   +'<tr style=\"background:#F7E5E4\"><th>Caz</th><th>Responsabil</th><th>Termen</th><th>Strâns</th><th>Țintă</th><th>Progres</th><th>Stare</th></tr>';\r\n  CAZURI.filter(c=>!c.sters).forEach(cz=>{H+='<tr><td>'+esc(cz.nume)+'</td><td>'+esc(cz.resp)+'</td><td>'+cz.zile+' zile</td><td>'+eur(cz.strans||0)+'</td><td>'+eur(cz.tinta||0)+'</td><td>'+procCaz(cz)+'%</td><td>'+(cz.gata?'încheiat':'în lucru')+'</td></tr>';});\r\n  H+='</table><h2>Ce s-a realizat, pe persoane</h2>';\r\n  ECHIPA.forEach(p=>{\r\n    const d=perPers[p];H+='<h3>'+p+' — '+d.gata+' sarcini · '+ore(d.minGata)+' din '+ore(d.minTot)+' realizate</h3><ul style=\"font-size:12px\">';\r\n    if(!d.lista.length)H+='<li>Nicio sarcină bifată în această perioadă.</li>';\r\n    d.lista.forEach(x=>H+='<li>'+x.iso+' — '+esc(x.t)+' <span style=\"color:#888\">· '+x.dur+' min</span>'+(x.caz?' <i>('+esc(x.caz)+')</i>':'')+'</li>');\r\n    H+='</ul>';\r\n  });\r\n  H+='<p style=\"color:#888;font-size:11px;margin-top:26px\">Generat automat din planificatorul de cazuri.</p></body></html>';\r\n  return H;\r\n}\r\nfunction perioadaRaport(){\r\n  const z=prompt('Raport pentru ce perioadă?\\n\\n1 = ziua de azi\\n7 = ultima săptămână\\n30 = ultima lună','7');\r\n  if(!z)return null;\r\n  return Math.max(1,Math.min(62,+z||7));\r\n}\r\nfunction numeRaport(zile,ext){return 'raport-'+(zile===1?'zilnic':zile<=7?'saptamanal':'lunar')+'-'+todayIso()+'.'+ext;}\r\nfunction raportPdf(){\r\n  const zile=perioadaRaport(); if(!zile)return;\r\n  if(typeof html2pdf!=='function'){toast('PDF încă se încarcă — mai încearcă în câteva secunde');return;}\r\n  const H=construiesteRaport(zile);\r\n  const parsed=new DOMParser().parseFromString(H,'text/html');\r\n  const cont=document.createElement('div');\r\n  cont.style.cssText='font-family:Calibri,Arial,sans-serif;width:760px;padding:24px;color:#111;background:#fff';\r\n  cont.innerHTML=parsed.body.innerHTML;\r\n  document.body.appendChild(cont);\r\n  toast('Se generează PDF-ul…');\r\n  html2pdf().set({margin:[10,10,12,10],filename:numeRaport(zile,'pdf'),\r\n    image:{type:'jpeg',quality:.96},\r\n    html2canvas:{scale:2,useCORS:true,backgroundColor:'#ffffff'},\r\n    jsPDF:{unit:'mm',format:'a4',orientation:'portrait'},\r\n    pagebreak:{mode:['css','legacy'],avoid:'tr'}})\r\n    .from(cont).save().then(function(){cont.remove();toast('PDF descărcat ✓');})\r\n    .catch(function(){cont.remove();toast('Nu s-a putut genera PDF-ul');});\r\n}\r\nfunction raportWord(){\r\n  const zile=perioadaRaport(); if(!zile)return;\r\n  const H=construiesteRaport(zile);\r\n  const a=document.createElement('a');\r\n  a.href=URL.createObjectURL(new Blob(['\\ufeff'+H],{type:'application/msword'}));\r\n  a.download='raport-'+(zile===1?'zilnic':zile<=7?'saptamanal':'lunar')+'-'+todayIso()+'.doc';a.click();\r\n  toast('Raport descărcat ✓');\r\n}\r\nfunction toast(m){const t=document.getElementById('toast');t.textContent=m;t.style.opacity='1';clearTimeout(t._h);t._h=setTimeout(()=>t.style.opacity='0',1700);}\r\nloadAll();\r\n</script>\r\n\r\n<script>\r\n(function(){\r\n  function norm(s){\r\n    return (s||'').toString().trim().toLowerCase()\r\n      .normalize('NFD').replace(/[\\u0300-\\u036f]/g,'')\r\n      .replace(/[\\u0219\\u015f\\u0163\\u0165]/g,function(c){return c==='\\u0163'||c==='\\u0165'?'t':'s';})\r\n      .replace(/\\u021b/g,'t');\r\n  }\r\n  function firstToken(s){ return norm(s).split(/[\\s@._-]+/)[0]||''; }\r\n  function mapName(login){\r\n    if(!login) return '';\r\n    var nl=norm(login), fl=firstToken(login);\r\n    for(var i=0;i<TOTI.length;i++){\r\n      var p=TOTI[i], np=norm(p);\r\n      if(np===nl||np===fl||firstToken(p)===fl) return p;\r\n    }\r\n    return '';\r\n  }\r\n  function apply(){\r\n    var login=''; try{ login=localStorage.getItem('soi-plan2-loginname')||''; }catch(e){}\r\n    var m=mapName(login);\r\n    if(!m) return;\r\n    try{ localStorage.setItem('soi-plan2-user',m); }catch(e){}\r\n    if(typeof setUser==='function' && typeof USER!=='undefined' && USER!==m) setUser(m);\r\n    var who=document.getElementById('whoami');\r\n    if(who){\r\n      var box=who.closest('.userbox');\r\n      if(box) box.innerHTML='Ești logat: <b>'+m+'</b>';\r\n    }\r\n  }\r\n  try{ apply(); }catch(e){}\r\n  setTimeout(function(){ try{ apply(); }catch(e){} }, 500);\r\n})();\r\n</script>\r\n</body>\r\n</html>\r\n";
